function activateTab(tabId){
  const btn=[...document.querySelectorAll('.tab-btn')].find(b=>b.dataset.tab===tabId);
  if(btn) btn.click();
}

function activateTabAndScroll(tabId, elementId){
  activateTab(tabId);
  setTimeout(()=>{
    const el=document.getElementById(elementId);
    if(el)el.scrollIntoView({behavior:'smooth',block:'start'});
  },180);
}
