  nominalChart:{tab:'tab-rates',recommendation:'Log opcional: conserva las nueve series del Lineal',ticks:[1,3,10,30,100,300],texts:['1','3','10','30','100','300'],linearRangemode:null,filteredLog:true,filteredHelp:'Ninguna serie se oculta: inflación, tasas y brecha usan el eje Log; las cuatro series monetarias permanecen en el eje derecho lineal.',logLabel:'Log · mismas series',linearReading:'nueve series · ambos ejes lineales',logReading:'nueve series · tasas Log + posiciones financieras lineales',logStatus:'Vista mixta: las cinco series de tasas y brecha usan Log; las cuatro series monetarias conservan el eje derecho lineal. No falta ningún campo del Lineal.',customApply:applyNominalChartScale},
