function meliFxMonthsForLabel(label){
  if(label==='1T26') return ['2026-01-01','2026-02-01','2026-03-01'];
  const year=String(label);
  return bcraData.fx.dates.filter(d=>d.startsWith(year+'-'));
}
function meliOfficialFxAverage(label){
  const months=meliFxMonthsForLabel(label);
  const map=new Map(bcraData.fx.dates.map((d,i)=>[d,bcraData.fx.level[i]]));
  const vals=months.map(d=>map.get(d)).filter(Number.isFinite);
  return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;
}
function meliArsRows(){
  return meliBenefitData.labels.map((label,i)=>{
    const usd= meliKnownTotalAt(i);
    const fx= meliOfficialFxAverage(label);
    const arsBn=Number.isFinite(fx)?usd*fx/1000:null; // USD M × ARS/USD = ARS M; /1000 = ARS mil M
    return {label,usd,fx,arsBn};
  });
}
function meliCpiRatioFromPension(date){
  if(typeof powerPensionEffective==='undefined') return null;
  const i=powerPensionEffective.dates.indexOf(date);
  if(i<0)return null;
  const baseNom=powerPensionEffective.minimum[0]+powerPensionEffective.bonus[0];
  const nom=powerPensionEffective.minimum[i]+powerPensionEffective.bonus[i];
  const real=powerPensionEffective.yNov[i];
  return Number.isFinite(real)&&real!==0 ? (nom/baseNom)/(real/100) : null;
}
function meliAverageCpiRatio(label){
  let months=[];
  if(label==='1T26') months=['2026-01-01','2026-02-01','2026-03-01'];
  else if(label==='2024'||label==='2025') months=Array.from({length:12},(_,i)=>`${label}-${String(i+1).padStart(2,'0')}-01`);
  const vals=months.map(meliCpiRatioFromPension).filter(Number.isFinite);
  return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;
}
function meliRecentConversion(){
  const junRatio=meliCpiRatioFromPension('2026-06-01');
  const wanted=new Set(['2024','2025','1T26']);
  const rows=meliArsRows().filter(r=>wanted.has(r.label)).map(r=>{
    const avgCpi=meliAverageCpiRatio(r.label);
    const jun26Bn=(Number.isFinite(r.arsBn)&&Number.isFinite(avgCpi)&&Number.isFinite(junRatio)) ? r.arsBn*(junRatio/avgCpi) : null;
    return {...r,avgCpi,jun26Bn};
  });
  return {rows,nominalBn:rows.reduce((a,r)=>a+(r.arsBn||0),0),jun26Bn:rows.reduce((a,r)=>a+(r.jun26Bn||0),0)};
}
