let consumptionMetric = 'total';
let consumptionRendered = false;

function coFmt(v,d=1) {
  if(v==null || !Number.isFinite(+v)) return '—';
  return (+v).toLocaleString('es-AR',{minimumFractionDigits:d,maximumFractionDigits:d});
}
function coPresidentLabel(y) {
  const transitions={2003:' · año de transición Duhalde → Néstor',2007:' · transición Néstor → CFK',2015:' · transición CFK → Macri',2019:' · transición Macri → Alberto',2023:' · transición Alberto → Milei'};
  return transitions[y]||'';
}
function coSeries(metric) {
  if(metric==='percap') return consumptionData.perCapIndex;
  if(metric==='growth') return consumptionData.growth;
  return consumptionData.totalIndex;
}
function coMandateShapes() { return mandateShapesDate('2026-06-30'); }
function coMandateAnnotations(mobile) {
  const labels=mandateAnnotationsDate(mobile)
    .filter(a=>!(a.text||'').toString().toLowerCase().includes('pandemia'))
    .map(a=>({
      ...a,
      y:mobile?1.025:1.035,
      font:{...a.font,size:mobile?8:10},
      borderpad:mobile?2:3
    }));
  const pandemic=pandemicDateAnnotations(mobile).map(a=>({
    ...a,
    y:mobile?.84:.91,
    text:mobile?'<b>pandemia</b><br>2020–2021':'pandemia 2020–2021',
    font:{...a.font,size:mobile?8:9},
    borderpad:mobile?3:4
  }));
  return labels.concat(pandemic);
}
function coChartAnnotations(mobile) {
  const a=coMandateAnnotations(mobile).slice();
  if(consumptionMetric!=='growth') {
    a.push({xref:'paper',x:.985,yref:'paper',y:mobile?.67:.76,text:'base 2023 = 100',showarrow:false,xanchor:'right',yanchor:'middle',font:{size:mobile?9:10,color:'#9a6b28'},bgcolor:'rgba(255,250,238,.94)',bordercolor:'rgba(207,154,70,.55)',borderwidth:1,borderpad:4});
    a.push({xref:'paper',x:.985,yref:'paper',y:.035,text:'1T-2026 parcial<br><b>+2,7% ia · +0,8% t/t</b>',showarrow:false,xanchor:'right',yanchor:'bottom',align:'right',font:{size:mobile?9:10,color:'#765f80'},bgcolor:'rgba(255,255,255,.96)',bordercolor:'rgba(218,201,229,.95)',borderwidth:1,borderpad:4});
  }
  return a;
}

function renderConsumptionMandateCards() {
  const root=document.getElementById('consumptionMandateCards'); if(!root) return;
  const ix=new Map(consumptionData.years.map((y,i)=>[y,i]));
  const change=(arr)=> arr.length<2 ? null : (arr[arr.length-1]/arr[0]-1)*100;
  root.innerHTML=consumptionMandates.map(m=>{
    const ids=m.years.map(y=>ix.get(y));
    const tot=ids.map(i=>consumptionData.totalIndex[i]);
    const pc=ids.map(i=>consumptionData.perCapIndex[i]);
    const dt=change(tot), dp=change(pc);
    const fmtDelta=(v)=> v==null ? '<span style="color:#967fa0">1 año disponible · sin tendencia interna</span>' : `<span class="co-delta" style="color:${v>=0?'#3b936d':'#c45d7e'}">${v>=0?'▲':'▼'} ${coFmt(Math.abs(v))}%</span>`;
    return `<div class="co-mandate-card"><h4>${m.name}</h4><div class="years">${m.years.join(' · ')}</div><div class="line"><b>Total real:</b> ${fmtDelta(dt)}</div><div class="line" style="margin-top:6px"><b>Por habitante:</b> ${fmtDelta(dp)}</div></div>`;
  }).join('');
}

function renderConsumption() {
  const mobile=window.innerWidth<=720;
  const years=consumptionData.years;
  const dates=years.map(y=>`${y}-07-01`);
  const series=coSeries(consumptionMetric);
  const isGrowth=consumptionMetric==='growth';
  const name=consumptionMetric==='percap'?'Consumo privado real por habitante':consumptionMetric==='growth'?'Variación anual del consumo privado real':'Consumo privado real total';
  const unit=isGrowth?'% interanual':'índice · 2023 = 100';
  const traces=[];

  if(isGrowth) {
    traces.push({x:dates,y:series,name,mode:'lines+markers',connectgaps:false,line:{color:'#9b6cdf',width:3},marker:{size:mobile?6:7,color:series.map(v=>v==null?'#ccc':v>=0?'#66b68e':'#e27696')},customdata:years.map((y,i)=>[y,consumptionData.method[i],coPresidentLabel(y)]),hovertemplate:'<b>%{customdata[0]}</b>%{customdata[2]}<br>'+name+'<br><b>%{y:.1f}%</b><br><span style="font-size:10px">%{customdata[1]}</span><extra></extra>'});
    traces.push({x:['2026-03-31'],y:[consumptionData.recent.q1_2026_yoy],name:'1T 2026 · parcial',mode:'markers',marker:{size:mobile?11:13,symbol:'diamond',color:'#e47da4',line:{color:'#fff',width:1.5}},customdata:[[consumptionData.recent.q1_2026_qoq_sa]],hovertemplate:'<b>1T 2026 · parcial</b><br>Consumo privado real: <b>+%{y:.1f}% ia</b><br>vs 4T-2025 desest.: <b>+%{customdata[0]:.1f}%</b><extra></extra>'});
  } else {
    const mainIdx=years.map((y,i)=> y>=2004&&y<=2023?series[i]:null);
    const oldIdx=years.map((y,i)=> y<=2004?series[i]:null);
    const recentIdx=years.map((y,i)=> y>=2023?series[i]:null);
    const custom=years.map((y,i)=>[y,consumptionData.method[i],coPresidentLabel(y)]);
    traces.push({x:dates,y:mainIdx,name:name+' · base 2004',mode:'lines+markers',connectgaps:false,line:{color:'#8d63d8',width:3},marker:{size:mobile?5:6},customdata:custom,hovertemplate:'<b>%{customdata[0]}</b>%{customdata[2]}<br>'+name+'<br><b>%{y:.1f}</b><br><span style="font-size:10px">%{customdata[1]}</span><extra></extra>'});
    traces.push({x:dates,y:oldIdx,name:'2002–03 · enlace histórico',mode:'lines+markers',connectgaps:false,line:{color:'#d19a55',width:2.5,dash:'dot'},marker:{size:mobile?5:6},customdata:custom,hovertemplate:'<b>%{customdata[0]}</b>%{customdata[2]}<br>'+name+'<br><b>%{y:.1f}</b><br><span style="font-size:10px">%{customdata[1]}</span><extra></extra>'});
    traces.push({x:dates,y:recentIdx,name:'2024–25 · extensión tasas oficiales',mode:'lines+markers',connectgaps:false,line:{color:'#e47da4',width:3,dash:'dash'},marker:{size:mobile?6:7},customdata:custom,hovertemplate:'<b>%{customdata[0]}</b>%{customdata[2]}<br>'+name+'<br><b>%{y:.1f}</b><br><span style="font-size:10px">%{customdata[1]}</span><extra></extra>'});
  }

  const shapes=coMandateShapes();
  const annotations=coChartAnnotations(mobile);
  if(!isGrowth) {
    shapes.push({type:'line',xref:'paper',x0:0,x1:1,y0:100,y1:100,line:{color:'#c9954f',width:1.5,dash:'dash'}});
  } else {
    shapes.push({type:'line',xref:'paper',x0:0,x1:1,y0:0,y1:0,line:{color:'#ad91b9',width:1.3,dash:'dash'}});
  }

  Plotly.react('consumptionChart',traces,{
    ...common,
    margin:{l:mobile?48:72,r:mobile?12:28,t:mobile?120:104,b:mobile?48:58},
    xaxis:{...common.xaxis,type:'date',range:['2001-10-01','2026-06-30'],dtick:mobile?'M36':'M24',tickformat:'%Y',tickangle:mobile?-35:0,fixedrange:true},
    yaxis:{...common.yaxis,title:unit,ticksuffix:isGrowth?'%':'',zeroline:false,fixedrange:true},
    legend:{...common.legend,orientation:'h',y:mobile?1.17:1.13,font:{size:mobile?9:11},x:0},
    hovermode:mobile?'closest':'x unified',shapes,annotations
  },{responsive:true,displaylogo:false,displayModeBar:false,scrollZoom:false,doubleClick:false});
  renderConsumptionMandateCards();
  renderConsumptionCategories();
  renderConsumptionMoreCategories();
  renderConsumptionHistory();
  consumptionRendered=true;
  setTimeout(bindPlotlyClickTracking,50);
}
function setConsumptionMetric(metric) {
  consumptionMetric=metric;
  document.getElementById('coMetricTotal')?.classList.toggle('active',metric==='total');
  document.getElementById('coMetricPerCap')?.classList.toggle('active',metric==='percap');
  document.getElementById('coMetricGrowth')?.classList.toggle('active',metric==='growth');
  if(document.getElementById('consumptionChart')?.data) renderConsumption();
}
