const workMetricMeta={
 unemployment:{label:'Desocupación',note:'% de la PEA'},employment:{label:'Empleo',note:'% de la población'},
 activity:{label:'Actividad',note:'% de la población'},underemployment:{label:'Subocupación',note:'% de la PEA'}
};
function workFmt(v,d=1){return Number(v).toLocaleString('es-AR',{minimumFractionDigits:d,maximumFractionDigits:d})}
function setWorkMetric(m){
 workMetric=m;
 document.getElementById('workMetricUnemployment')?.classList.toggle('active',m==='unemployment');
 document.getElementById('workMetricEmployment')?.classList.toggle('active',m==='employment');
 document.getElementById('workMetricActivity')?.classList.toggle('active',m==='activity');
 document.getElementById('workMetricUnderemployment')?.classList.toggle('active',m==='underemployment');
 renderWork();
}
function workMandateStats(start,end){
 const a=workRows.filter(r=>r.date>=start&&r.date<=end&&['activity','employment','unemployment','underemployment'].every(k=>Number.isFinite(r[k])));
 if(!a.length)return null;
 const avg=k=>a.reduce((s,r)=>s+r[k],0)/a.length;
 return {n:a.length,activity:avg('activity'),employment:avg('employment'),unemployment:avg('unemployment'),underemployment:avg('underemployment')};
}
function renderWorkMandateCards(){
 const root=document.getElementById('workMandateCards');if(!root)return;
 const d0=workPunctualRows[0],d1=workPunctualRows[workPunctualRows.length-1];
 const duhalde=`<div class="work-mandate-card"><h4>Eduardo Duhalde</h4><div class="years">may-2002 → may-2003 · EPH puntual · 3 ondas</div><div class="line"><b>Desocupación:</b> ${workFmt(d0.unemployment)}% → ${workFmt(d1.unemployment)}%<br><b>Empleo:</b> ${workFmt(d0.employment)}% → ${workFmt(d1.employment)}%<br><b>Actividad:</b> ${workFmt(d0.activity)}% → ${workFmt(d1.activity)}%<br><b>Subocupación:</b> ${workFmt(d0.underemployment)}% → ${workFmt(d1.underemployment)}%</div></div>`;
 const defs=[
  {name:'Néstor Kirchner',period:'3T-2003 → 2T-2007',start:'2003-09-30',end:'2007-06-30'},
  {name:'Cristina Fernández',period:'1T-2008 → 3T-2015',start:'2008-03-31',end:'2015-09-30',warn:true},
  {name:'Mauricio Macri',period:'2T-2016 → 3T-2019',start:'2016-06-30',end:'2019-09-30'},
  {name:'Alberto Fernández',period:'1T-2020 → 3T-2023',start:'2020-03-31',end:'2023-09-30'},
  {name:'Javier Milei',period:'1T-2024 → 1T-2026',start:'2024-03-31',end:'2026-03-31'}
 ];
 const rest=defs.map(d=>{
   const s=workMandateStats(d.start,d.end); if(!s)return '';
   const warn=d.warn?' · ⚠ serie con reservas':'';
   return `<div class="work-mandate-card"><h4>${d.name}</h4><div class="years">${d.period} · ${s.n} trimestres${warn}</div><div class="line"><b>Desocupación promedio:</b> ${workFmt(s.unemployment)}%<br><b>Empleo promedio:</b> ${workFmt(s.employment)}%<br><b>Actividad promedio:</b> ${workFmt(s.activity)}%<br><b>Subocupación promedio:</b> ${workFmt(s.underemployment)}%</div></div>`;
 }).join('');
 root.innerHTML=duhalde+rest;
}
