function downloadWorkCsv(){
 const h='periodo,actividad_pct,empleo_pct,desocupacion_pct,subocupacion_pct,metodologia\n';
 const p=workPunctualRows.map(r=>`${r.label},${r.activity},${r.employment},${r.unemployment},${r.underemployment},EPH puntual`);
 const c=workRows.map(r=>`${r.label},${r.activity??''},${r.employment??''},${r.unemployment??''},${r.underemployment??''},EPH continua`);
 const blob=new Blob(['\uFEFF'+h+[...p,...c].join('\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download='mercado_trabajo_eph_2002_2026.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
