function downloadWorkCsv(){
 const h='periodo,actividad_pct,empleo_pct,desocupacion_pct,subocupacion_pct\n';
 const lines=workRows.map(r=>`${r.date.slice(0,7)},${r.activity},${r.employment},${r.unemployment},${r.underemployment}`).join('\n');
 const blob=new Blob(['\uFEFF'+h+lines],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download='mercado_trabajo_eph_2016_2026.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
