function renderInvestmentMandateCards(){
  const root=document.getElementById('investmentMandateCards');if(!root)return;
  const defs=[
    {name:'Eduardo Duhalde',years:[2002],label:'2002'},
    {name:'Néstor Kirchner',years:[2004,2005,2006],label:'2004–2006'},
    {name:'Cristina Fernández',years:[2008,2009,2010,2011,2012,2013,2014],label:'2008–2014'},
    {name:'Mauricio Macri',years:[2016,2017,2018],label:'2016–2018'},
    {name:'Alberto Fernández',years:[2020,2021,2022],label:'2020–2022'},
    {name:'Javier Milei',years:[2024,2025],label:'2024–2025'}
  ];
  root.innerHTML=defs.map(d=>{
    const rows=investmentAnnual.filter(r=>d.years.includes(r.year));
    const avg=rows.reduce((s,r)=>s+r.total,0)/rows.length;
    const lo=rows.reduce((a,b)=>a.total<b.total?a:b), hi=rows.reduce((a,b)=>a.total>b.total?a:b);
    return `<div class="inv-mandate-card"><h4>${d.name}</h4><div class="years">${d.label} · años completos</div><div class="line"><b>Promedio inversión / PIB:</b> ${invFmt(avg)}%<br><b>Máximo:</b> ${hi.year} · ${invFmt(hi.total)}%<br><b>Mínimo:</b> ${lo.year} · ${invFmt(lo.total)}%</div></div>`;
  }).join('');
}
