 return a.map(([y,t])=>({xref:'x',yref:'paper',x:`${y}-07-01`,y:1.02,text:t,showarrow:false,font:{size:mobile?9:11,color:'#816b8b'},bgcolor:'rgba(255,255,255,.7)',borderpad:2}));
