function renderGrowthMandateCards(){
 const root=document.getElementById('growthMandateCards'); if(!root)return;
 const ix=new Map(growthData.years.map((y,i)=>[y,i]));
 root.innerHTML=growthMandates.map(m=>{
   const ids=m.years.map(y=>ix.get(y)); const g=ids.map(i=>growthData.growth[i]); const lev=ids.map(i=>growthData.levelIndex[i]);
   const pos=g.filter(v=>v>0).length,neg=g.filter(v=>v<0).length; const avg=grAvg(g);
   const traj=lev.length>1?((lev[lev.length-1]/lev[0]-1)*100):null;
   return `<div class="gr-mandate-card"><h4>${m.name}</h4><div class="years">${m.years.join(' · ')}</div><div class="line"><b>Crecimiento promedio:</b> <span class="gr-delta" style="color:${avg>=0?'#2f8b68':'#c24f70'}">${avg>=0?'+':''}${grFmt(avg)}%</span><br><b>Años:</b> ${pos} creciendo · ${neg} cayendo${traj===null?'':`<br><b>Nivel entre años completos:</b> ${traj>=0?'+':''}${grFmt(traj)}%`}</div></div>`;
 }).join('');
}
