 if(isGrowth){shapes.push({type:'line',xref:'paper',x0:0,x1:1,y0:avg,y1:avg,line:{color:'#cf9a46',width:1.6,dash:'dash'}});annotations.push({xref:'paper',x:.995,yref:'y',y:avg,text:`Promedio 2002–2025 · ${grFmt(avg)}%`,showarrow:false,xanchor:'right',yanchor:'bottom',font:{size:mobile?9:11,color:'#9a6b28'},bgcolor:'rgba(255,250,238,.88)',borderpad:3})}
 else {shapes.push({type:'line',xref:'paper',x0:0,x1:1,y0:100,y1:100,line:{color:'#c99743',width:1.5,dash:'dash'}})}
