    maps.r=mk(bcraData.reserve.dates,bcraData.reserve.stock); maps.rc=mk(bcraData.reserve.dates,bcraData.reserve.change); maps.p=mk(bcraData.intervention.dates,bcraData.intervention.purchase); maps.fx=mk(bcraData.fx.dates,bcraData.fx.level); maps.fxc=mk(bcraData.fx.dates,bcraData.fx.change); maps.b=mk(bcraData.rates.dates,bcraData.rates.badlar); maps.t=mk(bcraData.rates.dates,bcraData.rates.tamar);
