function sovereignPolicyForYear(c,year){
  if(!isSovereignContinuityFamily(sovereignPreset)){
    const effectiveGrowth=c.growth-c.primary*c.fiscalSensitivity;
    const gdpUsdGrowth=((1+effectiveGrowth/100)*(1+c.inflation/100)/(1+c.devaluation/100)-1)*100;
    return {...c,effectiveGrowth,gdpUsdGrowth,source:'slider constante'};
  }
  const terminal=sovereignContinuityPath[2031];
  let p={...(sovereignContinuityPath[year]||terminal)};
  if(sovereignPreset==='continuity_soft'){
    p.growth=Math.max(0.5,p.growth-1.2);
    p.inflation=p.inflation+2.0;
    p.rate=p.rate+0.7;
    p.gdpUsdGrowth=p.gdpUsdGrowth-2.4;
    p.label=(year<=2031?'continuidad floja ':'extensión floja ')+(year<=2031?year:'2031+');
  }else if(sovereignPreset==='continuity_finance'){
    p.growth=Math.max(0.8,p.growth-0.6);
    p.inflation=p.inflation+0.8;
    p.rate=p.rate+2.1;
    p.gdpUsdGrowth=p.gdpUsdGrowth-1.1;
    p.label=(year<=2031?'financiamiento tenso ':'extensión tensa ')+(year<=2031?year:'2031+');
  }else if(sovereignPreset==='continuity_reserves'){
    p.growth=Math.max(1.0,p.growth-0.4);
    p.inflation=p.inflation+1.0;
    p.rate=p.rate+0.7;
    p.gdpUsdGrowth=p.gdpUsdGrowth-1.6;
    p.label=(year<=2031?'reservas débiles ':'extensión con reservas débiles ')+(year<=2031?year:'2031+');
  }
  return {
    ...c,
    growth:p.growth,
    inflation:p.inflation,
    primary:p.primary,
    rate:p.rate,
    effectiveGrowth:p.growth,
    gdpUsdGrowth:p.gdpUsdGrowth,
    source:year<=2031?p.label:'extensión terminal 2031'
  };
}

