function sovereignBase(){
  const i=debtPublicData.years.indexOf(2026);
  const debt=debtPublicData.stockUsd[i], debtGdp=debtPublicData.debtGdp[i], foreignShare=debtPublicData.foreignCurrency[i]/100;
  const gdp=debt/(debtGdp/100);
  const reserveMap=new Map(bcraData.reserve.dates.map((d,j)=>[d,bcraData.reserve.stock[j]]));
  const reserves=reserveMap.get('2026-03-01') ?? 42052;
  return {debt,debtGdp,foreignShare,gdp,reserves,date:'2026-03-31'};
}
