function sovereignSimulate(c){
  const base=sovereignBase(); let debt=base.debt,gdp=base.gdp,reserves=base.reserves,realIndex=100; const rows=[]; let reserveExhaustion=null,firstStress=null;
  rows.push({year:'1T-2026',debt,gdp,reserves,realIndex,debtGdp:100*debt/gdp,reserveDebt:100*reserves/debt,interest:null,interestRevenue:null,grossNeed:null,newBorrowing:null,externalBalance:null,debtReserveInflow:null,externalService:null,effectiveGrowth:null,gdpUsdGrowth:null,reserveGap:0,stressReasons:[]});
  for(let n=1;n<=c.horizon;n++){
    const year=2026+n;
    const policy=sovereignPolicyForYear(c,year);
    const effectiveGrowth=policy.effectiveGrowth;
    realIndex*=1+effectiveGrowth/100;
    const gdpUsdGrowth=policy.gdpUsdGrowth;
    const interest=debt*policy.rate/100;

    // Feedback fiscal de continuidad:
    // 2027-2031 sigue el primario del FMI.
    // Desde 2032, el ancla pasa a resultado financiero ≈ 0:
    // primario ≈ intereses / PIB. Así el esfuerzo fiscal se relaja si baja la carga de intereses.
    let appliedPrimary=policy.primary;
    let fiscalRule=policy.source;
    if(isSovereignContinuityFamily(sovereignPreset) && year>2031){
      const interestPctGdp=gdp>0 ? 100*interest/gdp : 0;
      appliedPrimary=Math.max(0,interestPctGdp);
      fiscalRule='feedback fiscal · balance total ≈ 0';
    }

    const primaryAmount=gdp*appliedPrimary/100;
    const fiscalGap=Math.max(0,interest-primaryAmount);
    const fiscalExcess=Math.max(0,primaryAmount-interest);
    const maturities=debt*c.maturities/100;
    const rolled=maturities*c.rollover/100;
    const principalPaid=maturities-rolled;
    const grossNeed=maturities+fiscalGap;
    const newBorrowing=rolled+fiscalGap;
    let debtNext=Math.max(0,debt-maturities+newBorrowing-fiscalExcess);
    const externalBalance=gdp*c.external/100;
    const foreignBorrowing=newBorrowing*base.foreignShare;
    const debtReserveInflow=foreignBorrowing*c.debtToReserves/100;
    const externalService=(interest+principalPaid+fiscalExcess)*base.foreignShare*c.reserveService/100;
    const rawReserves=reserves+externalBalance+debtReserveInflow-externalService;
    const reserveGap=Math.max(0,-rawReserves); const reservesNext=Math.max(0,rawReserves);
    if(reserveGap>0&&!reserveExhaustion)reserveExhaustion=year;
    const gdpNext=Math.max(1,gdp*(1+gdpUsdGrowth/100));
    const revenue=gdp*c.revenue/100;
    const debtGdp=100*debtNext/gdpNext;
    const reserveDebt=debtNext>0?100*reservesNext/debtNext:null;
    const interestRevenue=revenue?100*interest/revenue:null;
    const stressReasons=[];
    if(debtGdp>=100)stressReasons.push('deuda/PIB ≥ 100%');
    if((interestRevenue||0)>=25)stressReasons.push('intereses/ingresos ≥ 25%');
    if(Number.isFinite(reserveDebt)&&reserveDebt<=5)stressReasons.push('reservas/deuda ≤ 5%');
    if(!firstStress&&stressReasons.length)firstStress={year,reasons:[...stressReasons]};
    const overallBalancePct=appliedPrimary-(revenue?100*interest/gdp:0);
    rows.push({year:String(year),debt:debtNext,gdp:gdpNext,reserves:reservesNext,realIndex,debtGdp,reserveDebt,interest,interestRevenue,grossNeed,newBorrowing,externalBalance,debtReserveInflow,externalService,effectiveGrowth,gdpUsdGrowth,reserveGap,stressReasons,policyGrowth:policy.growth,policyInflation:policy.inflation,policyPrimary:appliedPrimary,policyRate:policy.rate,policySource:fiscalRule,overallBalancePct});
    debt=debtNext;gdp=gdpNext;reserves=reservesNext;
  }
  return {base,rows,reserveExhaustion,firstStress};
}
function sovereignRenderBaseline(base){
  const el=document.getElementById('sovereignBaseline');if(!el)return;
  el.innerHTML=`<div class="sov-base-card"><div class="tag">Foto inicial · deuda bruta</div><div class="big">${sovMoney(base.debt)}</div><div class="mini">Punto de partida del simulador al 31/03/2026.</div></div><div class="sov-base-card"><div class="tag">Foto inicial · deuda / PIB</div><div class="big">${sovFmt(base.debtGdp)}%</div><div class="mini">Mide cuánto pesa la deuda respecto del tamaño de la economía en USD.</div></div><div class="sov-base-card"><div class="tag">Foto inicial · reservas brutas</div><div class="big">${sovMoney(base.reserves)}</div><div class="mini">Es el colchón externo desde el que arranca el escenario.</div></div><div class="sov-base-card"><div class="tag">Composición de referencia</div><div class="big">${sovFmt(base.foreignShare*100)}%</div><div class="mini">Parte de la deuda en moneda extranjera usada para aproximar pagos externos.</div></div>`;
}
function sovereignStatus(sim,c){
  const end=sim.rows.at(-1); const el=document.getElementById('sovereignStatus');if(!el)return;
  let cls='good', title='Lectura rápida: escenario sin alarma didáctica fuerte', bits=[];
  if(sim.firstStress){
    cls='warn';
    title=`Primer estrés didáctico en ${sim.firstStress.year}`;
    bits.push(sim.firstStress.reasons.join(' + '));
  }
  if(sim.reserveExhaustion){
    cls='bad';
    bits.push(`las reservas teóricas llegan a cero en ${sim.reserveExhaustion}`);
    if(!sim.firstStress)title=`Lectura rápida: el escenario se queda sin colchón externo en ${sim.reserveExhaustion}`;
  }
  if(end.debtGdp>=100)bits.push(`la deuda termina en ${sovFmt(end.debtGdp)}% del PIB`);
  if((end.interestRevenue||0)>=25)bits.push(`los intereses absorben ${sovFmt(end.interestRevenue)}% de los ingresos fiscales supuestos`);
  if(Number.isFinite(end.reserveDebt)&&end.reserveDebt<=5)bits.push(`las reservas finales equivalen a sólo ${sovFmt(end.reserveDebt)}% del stock de deuda`);
  if(!bits.length)bits.push(`la deuda/PIB termina en ${sovFmt(end.debtGdp)}%, los intereses/ingresos en ${sovFmt(end.interestRevenue||0)}% y ${Number.isFinite(end.reserveDebt)?'las reservas/deuda en '+sovFmt(end.reserveDebt)+'%':'la deuda llega a cero antes del final del horizonte'}`);
  el.className='sov-status '+cls; el.innerHTML=`<b>${title}.</b> ${bits.join(' · ')}.<br><span style="opacity:.82">Semáforo pedagógico: 100% deuda/PIB, 25% intereses/ingresos y 5% reservas/deuda son los mismos umbrales didácticos de la v78. Marcan el primer cruce; no son una sentencia automática de default.</span>`;
}
