function renderHealthEducationProvMandateCards() {
  const root=document.getElementById('healthEducationProvMandateCards');
  if(!root) return;
  const idx=new Map(healthEducationProvHistory.years.map((y,i)=>[y,i]));
  root.innerHTML=healthEducationProvMandates.map(m=>{
    const ix=m.years.map(y=>idx.get(y));
    const edu=ix.map(i=>healthEducationProvHistory.education[i]);
    const sal=ix.map(i=>healthEducationProvHistory.health[i]);
    return `<div class="he-mandate-card"><h4>${m.name}</h4><div class="years">${m.years.join(' · ')}</div><div class="line"><b>Educación y Cultura:</b> promedio ${heFmt(heAvg(edu),1)}%<br><b>Salud:</b> promedio ${heFmt(heAvg(sal),1)}%</div></div>`;
  }).join('');
}
function renderHealthEducationMandateCards() {
  const root=document.getElementById('healthEducationMandateCards');
  if(!root) return;
  const index=new Map(healthEducationData.years.map((y,i)=>[y,i]));
  root.innerHTML=healthEducationMandates.map(m=>{
    const ix=m.years.map(y=>index.get(y));
    const edu=ix.map(i=>healthEducationData.education[i]);
    const sal=ix.map(i=>healthEducationData.health[i]);
    const avg=a=>a.reduce((s,v)=>s+v,0)/a.length;
    const trend=(a)=> a.length<2
      ? '<span style="color:#967fa0">1 año completo disponible · sin tendencia interna</span>'
      : `<span class="delta" style="color:${a[a.length-1]-a[0]>=0?'#3c966e':'#c25f7d'}">${a[a.length-1]-a[0]>=0?'▲':'▼'} ${heFmt(Math.abs(a[a.length-1]-a[0]))} pp</span> entre ${m.years[0]} y ${m.years[m.years.length-1]}`;
    return `<div class="he-mandate-card"><h4>${m.name}</h4><div class="years">${m.years.join(' · ')}</div><div class="line"><b>Educación:</b> promedio ${heFmt(avg(edu))}% PIB<br>${trend(edu)}</div><div class="line" style="margin-top:7px"><b>Salud total:</b> promedio ${heFmt(avg(sal))}% PIB<br>${trend(sal)}</div></div>`;
  }).join('');
}
