function powerPensionEffectiveTrace(){
  return {
    x:powerPensionEffective.dates,
    y:powerPensionEffective.yNov,
    customdata:powerPensionEffective.yNov.map((v,i)=>[
      `${v>=100?'▲':'▼'} ${Math.abs(v-100).toFixed(2).replace('.',',')}% vs nov-2023`,
      powerPensionEffective.minimum[i],
      powerPensionEffective.bonus[i],
      powerPensionEffective.minimum[i]+powerPensionEffective.bonus[i]
    ]),
    name:'Jubilación mínima + bono máximo',
    mode:'lines+markers',
    connectgaps:false,
    legendgroup:'pension-effective',
    line:{color:'#8f6db5',width:2.7,dash:'dashdot'},
    marker:{size:4.5,symbol:'circle-open',color:'#8f6db5'},
    hovertemplate:
      '<b>Mínima + bono máximo</b>: <b>%{y:.2f}</b> · %{customdata[0]}' +
      '<extra></extra>'
  };
}

const powerHistoricalPrefixDates = powerHistoricalMonthly.dates.slice(0,-1); // ene-2002 .. dic-2016; ene-2017 ya existe en la serie moderna
powerData.dates = powerHistoricalPrefixDates.concat(powerModernDatesOriginal);
powerData.series.forEach(s => {
  s.yNov = Array(powerHistoricalPrefixDates.length).fill(null).concat(s.yNov);
  s.yJan = Array(powerHistoricalPrefixDates.length).fill(null).concat(s.yJan);
});

function powerStatusData(values) {
  return values.map(v => {
    if (v === null || v === undefined) return null;
    const d = v - 100;
    const abs = Math.abs(d).toFixed(2);
    if (Math.abs(d) < 0.005) return '≈ igual que la base (0,00%)';
    return d < 0 ? `↓ ${abs}% peor que la base` : `↑ ${abs}% mejor que la base`;
  });
}

function powerHistoricalTrace(base, key, name, color, derived=false) {
  const vals = base === 'nov' ? powerHistoricalMonthly[key].yNov : powerHistoricalMonthly[key].yJan;
  const deflatorNote = powerHistoricalMonthly.dates.map(d => d <= '2007-01-01'
    ? 'Deflactor: IPC-GBA histórico · INDEC'
    : 'Deflactor: IPC Provincias · CIFRA');
  const method = derived
    ? 'Salario: total registrado histórico derivado con ponderadores oficiales 62,65% / 37,35%'
    : 'Salario: Índice de Salarios histórico · INDEC';
  return {
    x: powerHistoricalMonthly.dates,
    y: vals,
    customdata: vals.map((v,i)=>[powerStatusData([v])[0], method, deflatorNote[i]]),
    name: name,
    mode:'lines',
    connectgaps:false,
    showlegend:false,
    legendgroup:key,
    line:{color, width:derived?1.8:2.15, dash:derived?'dot':'solid'},
    opacity:derived?.78:.86,
    hovertemplate:
      '<b>' + name.replace(' · histórico reconstruido','').replace(' · histórico INDEC','') + '</b>: ' +
      '<b>%{y:.2f}</b> · %{customdata[0]}' +
      '<extra></extra>'
  };
}




