function powerAccumulatedGap(){
  const dates=powerTotalAllOfficial.dates;
  const vals=powerTotalAllOfficial.yNov;
  const baseDate='2023-11-01';
  const bi=dates.indexOf(baseDate);
  if(bi<0)return null;

  // Derecha: dic-2023 → último dato. Saldo neto acumulado.
  const rightX=[baseDate], rightY=[0];
  let net=0,grossLoss=0,recovered=0,worst=0,worstDate=baseDate;
  for(let i=bi+1;i<dates.length;i++){
    const gap=vals[i]/100-1;
    if(gap<0) grossLoss+=-gap;
    else recovered+=gap;
    net+=gap;
    if(net<worst){worst=net;worstDate=dates[i]}
    rightX.push(dates[i]);
    rightY.push(net);
  }

  // Izquierda: misma cantidad de meses que la derecha, recorridos hacia atrás.
  const mirrorMonths=dates.length-bi-1;
  const leftStart=Math.max(0,bi-mirrorMonths);
  const leftYMap=new Map([[baseDate,0]]);
  let mirror=0;
  for(let i=bi-1;i>=leftStart;i--){
    mirror+=vals[i]/100-1;
    leftYMap.set(dates[i],mirror);
  }
  const leftX=dates.slice(leftStart,bi+1);
  const leftY=leftX.map(d=>leftYMap.get(d));

  return {
    baseDate,leftX,leftY,rightX,rightY,
    mirrorMonths,leftStart:dates[leftStart],
    mirror,grossLoss,recovered,net,worst,worstDate,
    latestDate:dates.at(-1)
  };
}
function powerAccumFmt(v){
  return Math.abs(v).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2});
}
function powerAccumShortDate(iso){
  const [y,m]=iso.split('-');
  const names=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
  return `${names[Number(m)-1]}-${y}`;
}
