function powerTraces(base) {
  const modern = powerData.series.map((s,i) => {
    const vals = base === 'nov' ? s.yNov : s.yJan;
    const isEph=s.name.startsWith('Privado no registrado');
    const isPublic=s.name.startsWith('Público');
    const isRipte=s.name==='RIPTE';
    const isPensionBase=s.name.startsWith('Jubilación mínima base');
    return {
      x: powerData.dates,
      y: vals,
      customdata: powerStatusData(vals),
      name: s.name,
      mode: 'lines',
      connectgaps: false,
      legendgroup: i===0?'totalreg':i===1?'priv':i===2?'pub':s.name,
      opacity:isEph?.82:1,
      line: {
        color: powerPalette[i],
        width: isPublic?2.7:(isRipte?2.7:(isPensionBase?3.0:(isEph?2.45:2.3))),
        dash: isEph?'dot':(isRipte?'dash':(isPensionBase?'longdash':(isPublic?'solid':s.dash))),
        shape:'linear'
      },
      hovertemplate:
        '<b>' + (isEph?'No registrado (EPH)':(isPensionBase?'Jubilación mínima base':s.name)) + '</b>: ' +
        '<b>%{y:.2f}</b> · %{customdata}' +
        (isEph?' <span style="font-size:10px">· rezago ~5m</span>':'') +
        '<extra></extra>'
    };
  });
  const traces=[
    powerHistoricalTrace(base,'totalreg','Total registrado · histórico reconstruido',powerPalette[0],true),
    powerHistoricalTrace(base,'priv','Privado registrado · histórico INDEC',powerPalette[1],false),
    powerHistoricalTrace(base,'pub','Público registrado · histórico INDEC',powerPalette[2],false),
    powerTotalAllTrace(base),
    ...modern,
    ...powerAccumulatedTraces(base)
  ];
  if(base==='nov') traces.push(powerPensionEffectiveTrace());
  return traces;
}

