function switchPowerBase(base) {
  const range = base === 'nov' ? [60,225] : [45,180];
  const mobile = window.innerWidth <= 720;
  const decor = powerMandateDecorations(mobile, base);
  const chart = document.getElementById('powerChart');
  const currentXRange = chart?.layout?.xaxis?.range ? chart.layout.xaxis.range.slice() : ['2002-01-01','2026-08-01'];
  const updatePromise=Plotly.react('powerChart', powerTraces(base), {
    ...powerLayout,
    margin:{...powerLayout.margin,t:mobile?205:166},
    xaxis:{...powerLayout.xaxis,range:currentXRange,dtick:mobile?'M12':'M24'},
    yaxis:{...powerLayout.yaxis,range},
    yaxis2:{...powerLayout.yaxis2,title:mobile?'Acum. · sueldos-base':'Acumulado · sueldos-base',showticklabels:!mobile},
    shapes:decor.shapes,
    annotations:decor.annotations,
    legend:{...common.legend,orientation:mobile?'v':'h',y:mobile?1.03:1.14,font:{size:mobile?11:13,color:'#624d70'}},
    hovermode:mobile?'closest':'x unified',
    hoverlabel:{...common.hoverlabel,font:{color:'#4d365c',size:mobile?11:14},namelength:mobile?26:-1}
  }, powerConfig);
  document.getElementById('powerBaseNov').classList.toggle('active', base==='nov');
  document.getElementById('powerBaseJan').classList.toggle('active', base==='jan');
  const contextBase=document.getElementById('powerChartContextBase');
  if(contextBase)contextBase.textContent=base==='nov'?'nov-2023 · base = 100':'ene-2017 · base = 100';
  renderPowerAccumulatedSummary(base);
  updatePromise.then(()=>applyStoredChartScale('powerChart'));
}
document.getElementById('powerBaseNov').onclick = ()=>switchPowerBase('nov');
document.getElementById('powerBaseJan').onclick = ()=>switchPowerBase('jan');

// ---------------- Tab 2: Tasas ----------------
function decimalYearFromIso(iso) {
  const [y, m, d] = iso.split('-').map(Number);
  const start = Date.UTC(y, 0, 1);
  const current = Date.UTC(y, m - 1, d);
  const next = Date.UTC(y + 1, 0, 1);
  return y + (current - start) / (next - start);
}

const annualPointDates = annual.map(d => d.year === 2026 ? '2026-07-31' : `${d.year}-12-31`);
const annualPointX = annualPointDates.map(decimalYearFromIso);
const annualPointMeta = annual.map((d, i) => {
  const close = annualPointDates[i];
  if (d.year === 2023) return `cierre ${close} · 2023 anual mixto: ene–nov Alberto Fernández · dic Javier Milei`;
  if (d.year === 2026) return `cierre ${close} · 2026 parcial: ene–jul`;
  return `cierre ${close} · dato anual`;
});

// Solo desdoblamos 2023 en la serie de inflación para que el salto de diciembre
// quede visualmente después del 10/12/2023, sin volver pesado el gráfico.
const inflationAnnualX = [];
const inflationAnnualY = [];
const inflationAnnualMeta = [];

annual.forEach(d => {
  if (d.year === 2023) {
    // Acumulado ene–nov = (1 + 211,407644%) / (1 + 25,5%) - 1 ≈ 148,13%.
    inflationAnnualX.push(decimalYearFromIso('2023-11-30'));
    inflationAnnualY.push(148.133581);
    inflationAnnualMeta.push('cierre 2023-11-30 · acumulado ene–nov 2023 · Alberto Fernández');

    inflationAnnualX.push(decimalYearFromIso('2023-12-31'));
    inflationAnnualY.push(d.inflacion);
    inflationAnnualMeta.push('cierre 2023-12-31 · 2023 anual mixto · dic-23 (+25,5%) bajo Milei');
  } else {
    const close = d.year === 2026 ? '2026-07-31' : `${d.year}-12-31`;
    inflationAnnualX.push(decimalYearFromIso(close));
    inflationAnnualY.push(d.inflacion);
    inflationAnnualMeta.push(d.year === 2026
      ? `cierre ${close} · 2026 parcial: ene–jul`
      : `cierre ${close} · dato anual`);
  }
});

