function ratesUsuryMonthClose(ym){
  const [year, month]=ym.split('-').map(Number);
  return new Date(Date.UTC(year,month,0)).toISOString().slice(0,10);
}
function ratesUsuryMonthlyValue(r){
  return Number(r.impacto_hogar_total_ampliado);
}
function ratesUsuryWindow(rows,anchor){
  const x=[decimalYearFromIso(anchor)], y=[0], monthly=[0];
  let running=0;
  rows.forEach(r=>{
    const value=ratesUsuryMonthlyValue(r);
    running+=value;
    x.push(decimalYearFromIso(ratesUsuryMonthClose(r.fecha)));
    y.push(running/1e12);
    monthly.push(value/1e12);
  });
  return {x,y,monthly,total:running};
}
const ratesUsuryMirror=ratesUsuryWindow(ratesUsuryMirrorRows,'2021-03-31');
const ratesUsuryPost=ratesUsuryWindow(ratesUsuryPostRows,'2023-12-10');
const ratesUsuryEffect={
  x:ratesUsuryPost.x,
  y:ratesUsuryPost.y.map((value,index)=>value-(ratesUsuryMirror.y[index]??ratesUsuryMirror.y.at(-1))),
  monthly:ratesUsuryPost.monthly.map((value,index)=>value-(ratesUsuryMirror.monthly[index]??0))
};
function ratesDebtorWindow(rows,anchor){
  const x=[decimalYearFromIso(anchor)], y=[0], monthly=[0];
  let running=0;
  rows.forEach(r=>{
    const value=Number(r.impacto_hogar_banco_constante||0)+Number(r.impacto_hogar_fintech_constante||0);
    running+=value;
    x.push(decimalYearFromIso(ratesUsuryMonthClose(r.fecha)));
    y.push(running/1e12);
    monthly.push(value/1e12);
  });
  return {x,y,monthly,total:running};
}
const ratesDebtorMirror=ratesDebtorWindow(ratesUsuryMirrorRows,'2021-03-31');
const ratesDebtorPost=ratesDebtorWindow(ratesUsuryPostRows,'2023-12-10');
const ratesDebtorEffect={
  x:ratesDebtorPost.x,
  y:ratesDebtorPost.y.map((value,index)=>value-(ratesDebtorMirror.y[index]??ratesDebtorMirror.y.at(-1))),
  monthly:ratesDebtorPost.monthly.map((value,index)=>value-(ratesDebtorMirror.monthly[index]??0)),
  total:ratesDebtorPost.total-ratesDebtorMirror.total
};
function ratesUsuryAxis(mobile){
  const values=[...ratesUsuryMirror.y,...ratesUsuryPost.y,...ratesUsuryEffect.y,...ratesDebtorEffect.y];
  const low=Math.min(0,...values), high=Math.max(0,...values);
  const pad=Math.max(.35,(high-low)*.08);
  return {
    title:mobile?'$ B · posiciones':'Posiciones financieras · $ B lineal',
    overlaying:'y',side:'right',range:[low-pad,high+pad],fixedrange:true,
    showgrid:false,zeroline:true,zerolinecolor:'#d7bcc8',tickprefix:'$ ',ticksuffix:' B',
    tickfont:{color:'#8f4665'},titlefont:{color:'#8f4665'}
  };
}

