function ratesFmt(v,d=2){
  return Number(v).toLocaleString('es-AR',{minimumFractionDigits:d,maximumFractionDigits:d});
}
function ratesShort(iso){
  if(!iso)return '—';
  const [y,m]=iso.split('-');
  return ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'][Number(m)-1]+'-'+y;
}
