function getGiniMandate(dateStr) {
  if (dateStr < '2003-05-25') return 'Eduardo Duhalde';
  if (dateStr < '2007-12-10') return 'Néstor Kirchner';
  if (dateStr < '2015-12-10') return 'Cristina Fernández';
  if (dateStr < '2019-12-10') return 'Mauricio Macri';
  if (dateStr < '2023-12-10') return 'Alberto Fernández';
  return 'Javier Milei';
}

function formatGiniDate(dateStr) {
  return new Intl.DateTimeFormat('es-AR', {
    day:'2-digit', month:'short', year:'numeric', timeZone:'UTC'
  }).format(new Date(dateStr + 'T00:00:00Z'));
}

function getGiniMethodNote(dateStr, seriesLabel, periodLabel) {
  const notes = [];
  if (seriesLabel === 'EPH puntual') {
    notes.push('Serie puntual; no es homogénea de forma perfecta con la EPH continua posterior.');
  }
  if (dateStr >= '2007-04-01' && dateStr <= '2015-12-31') {
    notes.push('INDEC indicó que los datos posteriores a 1T2007 y hasta 4T2015 deben considerarse con reservas.');
  }
  if (dateStr === '2019-03-31') {
    notes.push('Desde 1T2019 se incorporan áreas faltantes; la cobertura no es estrictamente comparable con 2T2016–4T2018.');
  }
  if (dateStr === '2019-09-30') {
    notes.push('3T2019 no incluye Gran Resistencia; cobertura estimada: 98,5% de la población habitual de los 31 aglomerados.');
  }
  if (periodLabel && periodLabel.includes('sin dato')) {
    notes.push('No hay valor publicado para ese período.');
  }
  return notes.join(' ');
}

function buildGiniHoverText(dates, labels, seriesLabel, values) {
  return dates.map((dateStr, i) => {
    const note = getGiniMethodNote(dateStr, seriesLabel, labels[i]);
    return [
      '<b>' + labels[i] + '</b>',
      'Fecha: <b>' + formatGiniDate(dateStr) + '</b>',
      'Mandato: <b>' + getGiniMandate(dateStr) + '</b>',
      'Serie: ' + seriesLabel,
      'Gini: <b>' + Number(values[i]).toFixed(3) + '</b>',
      note ? '<span style="font-size:11px">⚠ ' + note + '</span>' : ''
    ].filter(Boolean).join('<br>');
  });
}

