// ---------------- Tab: Más allá de la pobreza ----------------
let structureRendered = false;
function structureCabaResponsiveMode(){
  const chartWidth=document.getElementById('structureCabaChart')?.clientWidth||window.innerWidth;
  if(window.innerWidth<=720)return 'mobile';
  if(window.innerWidth<=1050||chartWidth<=760)return 'compact';
  return 'desktop';
}
function structureCabaLegendNames(mode){
  return mode==='desktop'
    ? ['Pobreza','No pobre vulnerable','Medio frágil','Sector medio “clase media”','Acomodados']
    : ['Pobreza','Vulnerables','Medio frágil','Sector medio','Acomodados'];
}
function structureMobilityLegendNames(mode){
  return mode==='desktop'
    ? ['Nunca pobre','Salió de la pobreza','Entró en pobreza','Pobre ambos años']
    : ['Nunca pobre','Salió','Entró','Pobre ambos'];
}
function structureMobilityTopMargin(){
  if(window.innerWidth<=420)return 98;
  if(window.innerWidth<=720)return 82;
  return 105;
}
function structureCabaAnnotations(mode){
  const mobile=mode==='mobile',compact=mode!=='desktop';
  const labels=[
    {x:'2015-02-01',short:'CFK',full:'Cristina Fernández',color:'#9a5577',bg:'rgba(255,247,251,.94)',border:'rgba(236,167,197,.45)',xanchor:'left'},
    {x:'2017-12-01',short:'Macri',full:'Mauricio Macri',color:'#7253a8',bg:'rgba(251,248,255,.94)',border:'rgba(184,151,244,.45)'},
    {x:'2021-10-01',short:'Alberto',full:'Alberto Fernández',color:'#557a99',bg:'rgba(247,252,255,.94)',border:'rgba(160,201,235,.48)'},
    {x:'2026-04-01',short:'Milei',full:'Javier Milei',color:'#a04d73',bg:'rgba(255,247,250,.94)',border:'rgba(244,163,193,.5)',xanchor:'right'}
  ];
  return [
    ...pandemicDateAnnotations(mobile),
    ...labels.map((d,index)=>({
      x:d.x,y:index%2?1.078:1.018,yref:'paper',
      text:compact?d.short:d.full,showarrow:false,xanchor:d.xanchor||'center',
      font:{size:mobile?8:(compact?9:10),color:d.color,family:'Inter,system-ui,sans-serif'},
      bgcolor:d.bg,bordercolor:d.border,borderwidth:1,borderpad:compact?2:4
    }))
  ];
}
function getStructureMandate(dateStr) {
  if (dateStr < '2015-12-10') return 'Cristina Fernández';
  if (dateStr < '2019-12-10') return 'Mauricio Macri';
  if (dateStr < '2023-12-10') return 'Alberto Fernández';
  return 'Javier Milei';
}
