// -------- Mobile: cerrar tooltip al tocar fuera --------
//
// Plotly mantiene el hover "pegado" en touch. La estrategia:
// 1) detectamos si ya había tooltip al empezar el toque;
// 2) si el toque cae físicamente dentro del tooltip, no hacemos nada;
// 3) si cae afuera y NO seleccionó otro punto, limpiamos el hover;
// 4) repetimos un par de veces porque Plotly puede volver a pintar
//    el hover unos milisegundos después del touchend.

const plotIds = ['powerChart', 'nominalChart', 'realChart', 'ratesAccumChart', 'presChart', 'povertyChart', 'povertyMandateChart', 'socialLongChart', 'socialChangeChart', 'socialRecentChart', 'giniChart', 'giniSameQuarterChart', 'structureCabaChart', 'structureMobilityChart', 'structureRegionChart', 'structureNseChart', 'familyRegionChart', 'familyGeoChart', 'familyThresholdChart', 'familyNonOwnerChart', 'housingChart', 'housingTenureChart', 'housingHistoryChart', 'housingMortgageRealChart', 'housingRentReformChart', 'housingBuildChart', 'riskChart', 'bigMacChart', 'bigMacFxChart', 'wholesaleChart', 'wholesaleCurrentChart', 'healthEducationChart', 'healthEducationExecutionChart', 'healthEducationBridgeChart', 'growthChart', 'debtPublicChart', 'debtCreditorChart', 'debtCurrencyChart', 'tradeChart', 'bcraReserveChart', 'bcraDebtCompareChart', 'bcraInterventionChart', 'bcraFactorsChart', 'bcraFxChart', 'bcraRatesChart', 'debtSimChart', 'debtClassChart', 'sovereignSustainChart', 'sovereignReserveFlowChart'];

let touchStartedWithHover = false;
let touchStartedInsideTooltip = false;
let selectedAnotherPoint = false;

function tooltipBoxes() {
  return Array.from(document.querySelectorAll(
    '.hoverlayer .hovertext, .hoverlayer .axistext, .hoverlayer .legendtext'
  )).map(el => {
    try { return el.getBoundingClientRect(); }
    catch (_) { return null; }
  }).filter(Boolean);
}

function pointInsideTooltip(x, y) {
  return tooltipBoxes().some(r =>
    x >= r.left && x <= r.right && y >= r.top && y <= r.bottom
  );
}

function plotlyHoverIsOpen() {
  return tooltipBoxes().length > 0 ||
    !!document.querySelector('.hoverlayer .hoverline');
}

function reallyClosePlotlyHover() {
  plotIds.forEach(id => {
    const el = document.getElementById(id);
    if (!el || !el.data) return;

    try { Plotly.Fx.unhover(el); } catch (_) {}

    // Plotly guarda parte del estado internamente; limpiarlo evita
    // que reaparezca inmediatamente en algunos navegadores Android.
    try { el._hoverdata = undefined; } catch (_) {}
  });
}

function closeHoverRepeatedly() {
  reallyClosePlotlyHover();
  setTimeout(reallyClosePlotlyHover, 40);
  setTimeout(reallyClosePlotlyHover, 120);
  setTimeout(reallyClosePlotlyHover, 240);
}

// Si el usuario toca otro punto, queremos mostrar ESE nuevo tooltip,
// no cerrar todo.
function bindPlotlyClickTracking() {
  plotIds.forEach(id => {
    const el = document.getElementById(id);
    if (!el || typeof el.on !== 'function' || el.dataset.dismissBound === '1') return;

    el.dataset.dismissBound = '1';
    el.on('plotly_click', () => {
      selectedAnotherPoint = true;
    });
  });
}

document.addEventListener('pointerdown', (event) => {
  bindPlotlyClickTracking();

  touchStartedWithHover = plotlyHoverIsOpen();
  touchStartedInsideTooltip = touchStartedWithHover &&
    pointInsideTooltip(event.clientX, event.clientY);

  selectedAnotherPoint = false;
}, true);

document.addEventListener('pointerup', (event) => {
  if (!touchStartedWithHover) return;

  const endedInsideTooltip = pointInsideTooltip(event.clientX, event.clientY);

  if (touchStartedInsideTooltip || endedInsideTooltip) {
    touchStartedWithHover = false;
    return;
  }

  // Esperamos a saber si Plotly interpretó el toque como selección
  // de otro punto. Si no, era un toque "afuera": cerramos.
  setTimeout(() => {
    if (!selectedAnotherPoint) closeHoverRepeatedly();

    touchStartedWithHover = false;
    touchStartedInsideTooltip = false;
    selectedAnotherPoint = false;
  }, 90);
}, true);

// También cierra al tocar fuera de cualquier gráfico.
document.addEventListener('click', (event) => {
  const insidePlot = plotIds.some(id => document.getElementById(id)?.contains(event.target));
  if (!insidePlot && plotlyHoverIsOpen()) closeHoverRepeatedly();
}, true);

// Escape en desktop.
document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape') closeHoverRepeatedly();
});

// Las tabs se renderizan dinámicamente: volvemos a enlazar después.
setTimeout(bindPlotlyClickTracking, 250);
window.addEventListener('resize', () => setTimeout(bindPlotlyClickTracking, 120));


// -------- Navegación temporal mobile con slider HTML nativo --------
// Evita los bugs del rangeslider de Plotly en Android.

function addMonthsISO(iso, months) {
  const d = new Date(iso + 'T00:00:00');
  d.setMonth(d.getMonth() + months);
  return d.toISOString().slice(0,10);
}

function formatYear(iso) {
  return String(new Date(iso + 'T00:00:00').getFullYear());
}


function bindRatesTimelineFocus(){
  const toggle=document.getElementById('ratesFrom2015Only');
  if(!toggle||toggle.dataset.bound)return;
  toggle.dataset.bound='1';
  toggle.addEventListener('change',applyRatesTimelineFocus);
}

function applyRatesTimelineFocus(){
  const toggle=document.getElementById('ratesFrom2015Only');
  if(!toggle)return;
  const focused=toggle.checked;
  const status=document.getElementById('ratesTimelineStatus');
  const nominalSlider=document.getElementById('nominalRange');
  const realSlider=document.getElementById('realRange');
  const nominalControl=document.getElementById('nominalRangeControl');
  const realControl=document.getElementById('realRangeControl');

  if(status)status.textContent=focused?'Foco reciente · 2015 → jul-2026':'Vista completa / control manual';
  if(nominalSlider)nominalSlider.disabled=focused;
  if(realSlider)realSlider.disabled=focused;
  if(nominalControl)nominalControl.classList.toggle('rates-focus-disabled',focused);
  if(realControl)realControl.classList.toggle('rates-focus-disabled',focused);

  const nominalChart=document.getElementById('nominalChart');
  const realChart=document.getElementById('realChart');
  if(typeof Plotly==='undefined'||!nominalChart?.data||!realChart?.data)return;

  if(focused){
    Plotly.relayout('nominalChart',{'xaxis.autorange':false,'xaxis.range':[2014.55,2026.70]});
    Plotly.relayout('realChart',{'xaxis.autorange':false,'xaxis.range':['2019-01-01','2026-08-01']});
    const nf=document.getElementById('nominalRangeFrom'),nt=document.getElementById('nominalRangeTo');
    const rf=document.getElementById('realRangeFrom'),rt=document.getElementById('realRangeTo');
    if(nf)nf.textContent='2015'; if(nt)nt.textContent='2026';
    if(rf)rf.textContent='2019'; if(rt)rt.textContent='2026';
  }else if(window.innerWidth<=720){
    applyNominalRange();
    applyRealRange();
  }else{
    Plotly.relayout('nominalChart',{'xaxis.autorange':false,'xaxis.range':[2001.5,2026.70]});
    Plotly.relayout('realChart',{'xaxis.autorange':false,'xaxis.range':['2019-01-01','2026-08-01']});
  }
}

function bindPowerTimelineFocus(){
  const toggle=document.getElementById('powerFrom2015Only');
  if(!toggle||toggle.dataset.bound)return;
  toggle.dataset.bound='1';
  toggle.addEventListener('change',applyPowerTimelineFocus);
}

function applyPowerTimelineFocus(){
  const toggle=document.getElementById('powerFrom2015Only');
  if(!toggle)return;
  const focused=toggle.checked;
  const status=document.getElementById('powerTimelineStatus');
  const slider=document.getElementById('powerRange');
  const control=document.getElementById('powerRangeControl');
  const chart=document.getElementById('powerChart');

  if(status)status.textContent=focused?'Foco reciente · 2015 → jul-2026':'Vista completa / control manual';
  if(slider)slider.disabled=focused;
  if(control)control.classList.toggle('rates-focus-disabled',focused);
  if(typeof Plotly==='undefined'||!chart?.data)return;

  if(focused){
    Plotly.relayout('powerChart',{'xaxis.autorange':false,'xaxis.range':['2015-01-01','2026-08-01']});
    const from=document.getElementById('powerRangeFrom'),to=document.getElementById('powerRangeTo');
    if(from)from.textContent='2015';
    if(to)to.textContent='2026';
  }else if(window.innerWidth<=720){
    applyPowerRange();
  }else{
    Plotly.relayout('powerChart',{'xaxis.autorange':false,'xaxis.range':['2002-01-01','2026-08-01']});
  }
}

function setupNativeRanges() {
  // Poder adquisitivo: ventana de 48 meses.
  const power = document.getElementById('powerRange');
  if (power) {
    const maxStart = Math.max(0, powerData.dates.length - 49);
    power.max = String(maxStart);
    if (!power.dataset.ready) {
      power.value = String(maxStart);
      power.dataset.ready = '1';
      power.addEventListener('input', applyPowerRange);
    }
  }

  // Tasas nominales: ventana de 9 años.
  const nominal = document.getElementById('nominalRange');
  if (nominal && !nominal.dataset.ready) {
    nominal.min = '2002';
    nominal.max = '2018';
    nominal.value = '2018';
    nominal.step = '1';
    nominal.dataset.ready = '1';
    nominal.addEventListener('input', applyNominalRange);
  }

  // Tasas reales: ventana de 48 meses.
  const real = document.getElementById('realRange');
  if (real) {
    const maxStart = Math.max(0, modern.length - 49);
    real.max = String(maxStart);
    if (!real.dataset.ready) {
      real.value = String(maxStart);
      real.dataset.ready = '1';
      real.addEventListener('input', applyRealRange);
    }
  }
}

function applyPowerRange() {
  if (window.innerWidth > 720) return;
  const slider = document.getElementById('powerRange');
  const chart = document.getElementById('powerChart');
  if (!slider || !chart || !chart.data) return;

  const startIndex = Number(slider.value || 0);
  const endIndex = Math.min(startIndex + 48, powerData.dates.length - 1);
  const from = powerData.dates[startIndex];
  const to = powerData.dates[endIndex];

  Plotly.relayout('powerChart', {'xaxis.range':[from,to]});
  document.getElementById('powerRangeFrom').textContent = formatYear(from);
  document.getElementById('powerRangeTo').textContent = formatYear(to);
}

function applyNominalRange() {
  if (window.innerWidth > 720) return;
  const slider = document.getElementById('nominalRange');
  const chart = document.getElementById('nominalChart');
  if (!slider || !chart || !chart.data) return;

  const from = Number(slider.value || 2018);
  const to = Math.min(from + 8, 2026);
  // +0.75 is intentional: jul-2026 sits around 2026.58 in the decimal-year axis.
  Plotly.relayout('nominalChart', {'xaxis.range':[from - 0.45, to + 0.75]});
  document.getElementById('nominalRangeFrom').textContent = String(from);
  document.getElementById('nominalRangeTo').textContent = String(to);
}

function applyRealRange() {
  if (window.innerWidth > 720) return;
  const slider = document.getElementById('realRange');
  const chart = document.getElementById('realChart');
  if (!slider || !chart || !chart.data || !modern.length) return;

  const startIndex = Number(slider.value || 0);
  const endIndex = Math.min(startIndex + 48, modern.length - 1);
  const from = modern[startIndex].date;
  const to = modern[endIndex].date;

  Plotly.relayout('realChart', {'xaxis.range':[from,to]});
  document.getElementById('realRangeFrom').textContent = formatYear(from);
  document.getElementById('realRangeTo').textContent = formatYear(to);
}

setTimeout(() => {
  setupNativeRanges();
  applyPowerRange();
  applyNominalRange();
  applyRealRange();
  bindPowerTimelineFocus();
  applyPowerTimelineFocus();
  bindRatesTimelineFocus();
  applyRatesTimelineFocus();
}, 150);


function buildPowerCsvFromChart() {
  const modernByName = Object.fromEntries(powerData.series.map(s=>[s.name,s]));
  const histMap = {
    'Total registrado · histórico reconstruido': powerHistoricalMonthly.totalreg,
    'Privado registrado · histórico INDEC': powerHistoricalMonthly.priv,
    'Público registrado · histórico INDEC': powerHistoricalMonthly.pub
  };
  const headers=['fecha','tramo','metodologia','Total salarios incl. no registrado EPH','Total registrado','Privado registrado','Público registrado','Privado no registrado EPH','RIPTE','Jubilación mínima base','Jubilación mínima + bono máximo'];
  const rows=[headers.join(',')];
  // historical monthly, base Jan-2017=100 for easier audit of the splice
  for(let i=0;i<powerHistoricalMonthly.dates.length-1;i++) {
    const d=powerHistoricalMonthly.dates[i];
    const method=d<='2007-01-01'?'IS INDEC + IPC-GBA INDEC':'IS INDEC + IPC Provincias CIFRA';
    rows.push([d.slice(0,7),'histórico',method,'',powerHistoricalMonthly.totalreg.yJan[i],powerHistoricalMonthly.priv.yJan[i],powerHistoricalMonthly.pub.yJan[i],'','','',''].join(','));
  }
  // modern monthly: values displayed under nov-2023=100; source columns are original chart series
  const start=powerHistoricalPrefixDates.length;
  for(let i=start;i<powerData.dates.length;i++) {
    const d=powerData.dates[i];
    const vals=powerData.series.map(s=>s.yNov[i]);
    const totalAllIndex=powerTotalAllOfficial.dates.indexOf(d);
    const totalAll=totalAllIndex>=0?powerTotalAllOfficial.yNov[totalAllIndex]:'';
    const effIndex=powerPensionEffective.dates.indexOf(d);
    const eff=effIndex>=0?powerPensionEffective.yNov[effIndex]:'';
    rows.push([d.slice(0,7),'moderno','series oficiales + IPC nacional INDEC; total salarios oficial incluye EPH; mínima+bono reconstruida',totalAll,...vals,eff].map(v=>v??'').join(','));
  }
  return rows.join('\n');
}


