let bigMacRendered=false;
async function renderBigMac(){
 if(bigMacRendered)return; bigMacRendered=true; const el=document.getElementById('bigMacChart'); el.innerHTML='<div class="note">Cargando hamburguesas macroeconómicas… 🍔</div>';
 try{
  const url='https://raw.githubusercontent.com/TheEconomist/big-mac-data/master/output-data/big-mac-full-index.csv'; const txt=await(await fetch(url)).text();
  const rows=parseSimpleCsv(txt).filter(r=>r.iso_a3==='ARG'&&r.date>='2002-01-01'&&r.date<=DASHBOARD_SNAPSHOT_CUTOFF);
  const d=rows.map(r=>r.date), raw=rows.map(r=>+r.USD_raw*100), adj=rows.map(r=>r.USD_adjusted===''?null:+r.USD_adjusted*100), fx=rows.map(r=>+r.dollar_ex), ppp=rows.map((r,i)=>fx[i]*(1+(+r.USD_raw)));
  dynamicCsv.bigmac={filename:'big_mac_argentina_desde_2002.csv',content:'date,local_price,dollar_ex,dollar_price,USD_raw_pct,USD_adjusted_pct,ppp_bigmac_ars_usd\n'+rows.map((r,i)=>`${r.date},${r.local_price},${r.dollar_ex},${r.dollar_price},${raw[i]},${adj[i]??''},${ppp[i]}`).join('\n')};

  const bigMacWhy = {
    'Eduardo Duhalde': 'La salida de la Convertibilidad produjo una devaluación muy fuerte en 2002. El Big Mac argentino pasó a quedar extremadamente barato en dólares; la recuperación posterior refleja, entre otras cosas, estabilización del tipo de cambio y recomposición de precios internos.',
    'Néstor Kirchner': 'Tras el salto cambiario de 2002, la economía creció y los precios y salarios domésticos fueron recomponiéndose mientras el tipo de cambio nominal permaneció relativamente estable. Eso tendió a encarecer nuevamente a Argentina en dólares y acercar el índice hacia la paridad.',
    'Cristina Fernández': 'La inflación local fue corriendo por delante de un tipo de cambio administrado durante buena parte del período. Desde 2011 se endurecieron los controles cambiarios y apareció una brecha con mercados paralelos; por eso el Big Mac calculado con el tipo de cambio oficial puede mostrar una apreciación mayor que la que enfrentaba realmente quien necesitaba dólares.',
    'Mauricio Macri': 'La salida inicial del cepo corrigió parte de la apreciación cambiaria, pero las crisis de 2018 y 2019 provocaron fuertes depreciaciones del peso. El movimiento final del Big Mac refleja sobre todo esos saltos cambiarios y el posterior pass-through a precios.',
    'Alberto Fernández': 'Volvieron y se profundizaron controles cambiarios, coexistiendo un dólar oficial administrado con brechas amplias frente a dólares financieros y paralelos. Como The Economist usa una cotización de referencia de mercado/oficial según su metodología, la lectura argentina debe tomarse con especial cautela durante el cepo.',
    'Javier Milei': 'El inicio de la gestión tuvo una devaluación discreta muy grande en diciembre de 2023. Después, con inflación todavía alta y un crawling peg mucho más lento, el peso se apreció en términos reales durante 2024; desde abril de 2025 el régimen cambiario volvió a modificarse. Por eso dentro de la misma gestión pueden verse primero un abaratamiento brusco y luego una reversión parcial.'
  };

  function buildBigMacMandateReadings(){
    const names=['Eduardo Duhalde','Néstor Kirchner','Cristina Fernández','Mauricio Macri','Alberto Fernández','Javier Milei'];
    const cards=[];
    for(const name of names){
      const pts=rows.map((r,i)=>({r,i,p:presidentForDate(r.date)})).filter(x=>x.p===name);
      if(!pts.length) continue;
      const first=pts[0], last=pts[pts.length-1];
      const a=raw[first.i], b=raw[last.i];
      const distA=Math.abs(a), distB=Math.abs(b);
      if(Math.abs(distB-Math.abs(b))>1e-9 || Math.abs(distA-Math.abs(a))>1e-9){
        console.error('Big Mac card distance sanity check failed', {name,a,b,distA,distB});
      }

      const adjA=adj[first.i], adjB=adj[last.i];
      const hasAdj=Number.isFinite(adjA) && Number.isFinite(adjB);
      const adjDistA=hasAdj?Math.abs(adjA):null;
      const adjDistB=hasAdj?Math.abs(adjB):null;

      function verdictFromDistance(start,end){
        if(!Number.isFinite(start)||!Number.isFinite(end)) return {text:'sin comparación',cls:''};
        const delta=end-start;
        if(delta <= -5) return {text:'mejoró · más cerca de 0%',cls:'good'};
        if(delta >= 5) return {text:'empeoró · más lejos de 0%',cls:'bad'};
        return {text:'≈ cambió poco',cls:''};
      }

      const rawVerdict=verdictFromDistance(distA,distB);
      const adjVerdict=hasAdj?verdictFromDistance(adjDistA,adjDistB):{text:'sin datos suficientes',cls:''};

      const priceMove=b-a;
      let pesoMove='casi sin cambio neto';
      if(priceMove >= 5) pesoMove='el peso se encareció en términos Big Mac';
      else if(priceMove <= -5) pesoMove='el peso se abarató en términos Big Mac';

      let jointReading='Las dos medidas cuentan una historia parecida.';
      if(hasAdj){
        const rawImproves=distB < distA-5;
        const rawWorsens=distB > distA+5;
        const adjImproves=adjDistB < adjDistA-5;
        const adjWorsens=adjDistB > adjDistA+5;

        if(rawImproves && adjImproves){
          jointReading='Mejoró tanto contra EE.UU. como contra lo esperable para un país con nuestro nivel de ingresos.';
        }else if(rawWorsens && adjWorsens){
          jointReading='Empeoró tanto en la comparación simple como en la ajustada por nivel de ingresos.';
        }else if(rawImproves && !adjImproves){
          jointReading='Se acercó a EE.UU. en la comparación simple, pero esa mejora se debilita al ajustar por PIB: parte del movimiento puede explicarse por nuestro nivel de ingresos.';
        }else if(!rawImproves && adjImproves){
          jointReading='La comparación simple no mejora demasiado, pero sí la ajustada por PIB: relativo a países de ingresos parecidos, la valuación luce más alineada.';
        }else if(rawWorsens && !adjWorsens){
          jointReading='La comparación simple se alejó de 0%, pero el ajuste por PIB amortigua esa lectura.';
        }else if(!rawWorsens && adjWorsens){
          jointReading='La comparación simple parece estable, pero ajustada por PIB se aleja de lo esperable para nuestro nivel de ingresos.';
        }
      }

      const fmt=x=>(x>=0?'+':'')+x.toFixed(1).replace('.',',')+'%';
      const fmtDate=d=>new Date(d+'T00:00:00Z').toLocaleDateString('es-AR',{month:'short',year:'numeric',timeZone:'UTC'});
      const firstDate=fmtDate(first.r.date);
      const lastDate=fmtDate(last.r.date);
      const inherited = first.i>0 ? rows[first.i-1] : null;
      const inheritedRaw = inherited ? raw[first.i-1] : null;
      const inheritedAdj = inherited && Number.isFinite(adj[first.i-1]) ? adj[first.i-1] : null;
      const inheritedDate = inherited ? fmtDate(inherited.date) : null;
      const inheritedPres = inherited ? presidentForDate(inherited.date) : null;
      const gapMonths = inherited ? Math.round((new Date(first.r.date+'T00:00:00Z') - new Date(inherited.date+'T00:00:00Z')) / (1000*60*60*24*30.4)) : null;

      cards.push(`<div class="social-mandate-card">
        <h4>${name}</h4>

        ${inherited?`
          <div class="note" style="margin-bottom:10px;font-size:.8rem">
            <b>Dato heredado más cercano:</b> ${fmt(inheritedRaw)} <span style="opacity:.8">(${inheritedDate} · ${inheritedPres})</span>.
            La primera observación propia recién aparece en <b>${firstDate}</b>${gapMonths>=4?` · entre medio hay ~${gapMonths} meses sin relevo del índice.`:''}
          </div>
        `:''}

        <div class="line"><span>Raw · primera obs. propia</span><b>${fmt(a)}</b></div>
        <div class="line"><span>Raw · última obs. propia</span><b>${fmt(b)}</b></div>
        <div class="line"><span>Raw · distancia a 0%</span><b>${distA.toFixed(1).replace('.',',')} → ${distB.toFixed(1).replace('.',',')} pp</b></div>
        <div class="take">
          <b class="${rawVerdict.cls}">Raw: ${rawVerdict.text}</b><br>
          ${pesoMove}.<br>
          <span style="opacity:.78">${firstDate} → ${lastDate}</span>
        </div>

        ${hasAdj?`
          ${Number.isFinite(inheritedAdj)?`
            <div class="note" style="margin-top:10px;font-size:.78rem">
              <b>Ajustado PIB heredado:</b> ${fmt(inheritedAdj)} <span style="opacity:.8">(${inheritedDate})</span>
            </div>
          `:''}
          <div class="line" style="margin-top:10px"><span>Ajustado PIB · primera obs. propia</span><b>${fmt(adjA)}</b></div>
          <div class="line"><span>Ajustado PIB · última obs. propia</span><b>${fmt(adjB)}</b></div>
          <div class="line"><span>Ajustado PIB · distancia a 0%</span><b>${adjDistA.toFixed(1).replace('.',',')} → ${adjDistB.toFixed(1).replace('.',',')} pp</b></div>
          <div class="take">
            <b class="${adjVerdict.cls}">Ajustado por PIB: ${adjVerdict.text}</b>
          </div>
        `:`
          <div class="note" style="margin-top:10px"><b>Ajustado por PIB:</b> no hay datos suficientes en ambas puntas del mandato para calcular una mejora/empeoramiento consistente.</div>
        `}

        <div class="note good" style="margin-top:10px;font-size:.84rem">
          <b>Lectura conjunta:</b> ${jointReading}
        </div>

        <div class="note" style="margin-top:10px;font-size:.82rem">
          <b>Cómo se calcula:</b> en ambas medidas, “mejoró” significa acercarse a 0%. No significa automáticamente mejor bienestar ni mejor política económica.
        </div>
        <div class="note" style="margin-top:10px;font-size:.82rem"><b>¿Por qué?</b> ${bigMacWhy[name]}</div>
      </div>`);
    }
    const target=document.getElementById('bigMacMandateCards');
    if(target) target.innerHTML=cards.join('');
  }
  buildBigMacMandateReadings();

  function buildBigMacPlainConclusion(){
    const box=document.getElementById('bigMacPlainConclusion');
    if(!box) return;
    const alberto=rows.map((r,i)=>({r,i,p:presidentForDate(r.date)})).filter(x=>x.p==='Alberto Fernández');
    const milei=rows.map((r,i)=>({r,i,p:presidentForDate(r.date)})).filter(x=>x.p==='Javier Milei');
    if(!alberto.length || !milei.length){
      box.innerHTML='<span class="label">Conclusión</span><strong>No hay suficientes observaciones para comparar el cierre de Alberto con Milei.</strong>';
      return;
    }
    const prev=alberto[alberto.length-1];
    const first=milei[0];
    const last=milei[milei.length-1];
    const prevVal=raw[prev.i], firstVal=raw[first.i], lastVal=raw[last.i];
    const fmt=x=>(x>=0?'+':'')+x.toFixed(1).replace('.',',')+'%';
    const cheapExp=x=>x<0?'más barato':'más caro';
    const closer=Math.abs(lastVal)<Math.abs(prevVal);
    const moved=lastVal-prevVal;
    let direction='casi no cambió frente a lo que dejó Alberto';
    if(moved>=5) direction='el peso quedó más caro en términos Big Mac';
    else if(moved<=-5) direction='el peso quedó más barato en términos Big Mac';

    const balance = closer
      ? 'Hoy el indicador está <b>más cerca de la paridad</b> que en la última observación de Alberto.'
      : 'Hoy el indicador está <b>más lejos de la paridad</b> que en la última observación de Alberto.';

    const practical = lastVal<0
      ? 'Argentina sigue siendo relativamente barata en dólares según esta hamburguesa.'
      : 'Argentina aparece relativamente cara en dólares según esta hamburguesa.';

    box.innerHTML=`
      <span class="label">Si sólo te llevás una cosa de este tab 🍔</span>
      <strong>Milei recibió una Argentina que el Big Mac ya mostraba ${cheapExp(prevVal)} que EE.UU. (${fmt(prevVal)}). La última observación disponible da ${fmt(lastVal)}.</strong>
      En el primer dato de Milei el índice estaba en <b>${fmt(firstVal)}</b>; desde ahí hasta el último dato, ${direction}. ${balance}
      <br><br><b>En castellano:</b> ${practical}
      Eso <b>no significa automáticamente que la economía esté mejor</b>: acercarse a 0% puede ser una normalización después de una devaluación, pero si el peso se encarece demasiado sin que productividad y salarios acompañen, también puede generar atraso cambiario y pérdida de competitividad.
      <br><br><b>Comparación con lo heredado:</b> lo importante no es “más alto = mejor”; es si el movimiento acercó al país a una relación de precios más sostenible <i>sin</i> destruir poder adquisitivo o competitividad. Para responder eso hay que cruzar este tab con salario real, inflación y sector externo.
    `;
  }
  buildBigMacPlainConclusion();
  const mobile=window.innerWidth<=720;
  Plotly.newPlot('bigMacChart',[{x:d,y:raw,name:'Raw USD',mode:'lines+markers',line:{color:'#ef7da7',width:2.6},hovertemplate:'<b>%{x|%b %Y}</b><br>Raw USD: <b>%{y:.1f}%</b><extra></extra>'},{x:d,y:adj,name:'Ajustado por PIB',mode:'lines+markers',connectgaps:false,line:{color:'#7a67d4',width:2,dash:'dot'},hovertemplate:'<b>%{x|%b %Y}</b><br>Ajustado: <b>%{y:.1f}%</b><extra></extra>'}],{...common,margin:{l:mobile?55:72,r:mobile?12:28,t:mobile?155:130,b:70},xaxis:{...common.xaxis,type:'date',dtick:mobile?'M48':'M24',tickformat:'%Y',fixedrange:true},yaxis:{...common.yaxis,title:'Sobre/subvaluación vs USD (%)',zeroline:true,zerolinecolor:'#8d77a0',ticksuffix:'%',fixedrange:true},shapes:mandateShapesDate(),annotations:mandateAnnotationsDate(mobile),hovermode:mobile?'closest':'x unified'}, {responsive:true,displaylogo:false,displayModeBar:false});
  const fxCustom = d.map((date,i)=>{
    const gap = fx[i]-ppp[i];
    const pctGap = ppp[i] ? ((fx[i]/ppp[i])-1)*100 : 0;
    return [
      presidentForDate(date),
      ppp[i],
      gap,
      pctGap,
      gap>=0 ? 'peso más barato / más depreciado que la paridad Big Mac' : 'peso más caro / más apreciado que la paridad Big Mac'
    ];
  });

  const fxGuide = document.getElementById('bigMacFxGuide');
  if(fxGuide && d.length){
    const i=d.length-1;
    const latestGap = fx[i]-ppp[i];
    const latestPct = ppp[i] ? ((fx[i]/ppp[i])-1)*100 : 0;
    const side = latestGap>=0
      ? 'el dólar observado quedó <b>por arriba</b> de la paridad Big Mac'
      : 'el dólar observado quedó <b>por abajo</b> de la paridad Big Mac';
    const directAnswer = latestGap>=0
      ? '<b>Respuesta directa:</b> según el Big Mac, el dólar observado está <b>más caro</b> que esta referencia. Si uno mirara solamente este indicador, el “dólar Big Mac” sería más bajo.'
      : '<b>Respuesta directa:</b> según el Big Mac, el dólar observado está <b>más barato</b> que esta referencia. Si uno mirara solamente este indicador, el “dólar Big Mac” sería más alto.';

    fxGuide.innerHTML = `
      ${directAnswer}
      <br><br>
      <b>Último dato disponible (${new Date(d[i]+'T00:00:00Z').toLocaleDateString('es-AR',{month:'short',year:'numeric',timeZone:'UTC'})}):</b>
      dólar observado <b>$${Math.round(fx[i]).toLocaleString('es-AR')}</b> vs paridad Big Mac <b>$${Math.round(ppp[i]).toLocaleString('es-AR')}</b>.
      La diferencia es de <b>${Math.abs(latestGap).toFixed(0).replace('.',',')} ARS</b> (${latestPct>=0?'+':''}${latestPct.toFixed(1).replace('.',',')}% respecto de la paridad).
      <br><br>
      <b>Pero no significa “hay que mover el dólar hasta ahí”.</b> Es una referencia de precios relativos, no una recomendación cambiaria. Para hablar de un tipo de cambio sostenible hay que mirar además productividad, salarios, reservas, comercio exterior e inflación.
    `;
  }

  Plotly.newPlot('bigMacFxChart',[
    {
      x:d,
      y:fx,
      customdata:fxCustom,
      name:'Tipo de cambio observado',
      mode:'lines+markers',
      line:{color:'#6a84e8',width:2.3},
      hovertemplate:
        '<b>%{x|%b %Y}</b><br>'+
        'Mandato: <b>%{customdata[0]}</b><br>'+
        'Dólar observado: <b>$%{y:.0f}</b> ARS/USD<br>'+
        'Paridad Big Mac: <b>$%{customdata[1]:.0f}</b> ARS/USD<br>'+
        'Brecha: <b>%{customdata[2]:+.0f}</b> ARS · %{customdata[3]:+.1f}%<br>'+
        '%{customdata[4]}<extra></extra>'
    },
    {
      x:d,
      y:ppp,
      customdata:fxCustom,
      name:'Paridad Big Mac implícita',
      mode:'lines+markers',
      line:{color:'#e5a14f',width:2.3,dash:'dash'},
      hovertemplate:
        '<b>%{x|%b %Y}</b><br>'+
        'Mandato: <b>%{customdata[0]}</b><br>'+
        'Paridad Big Mac: <b>$%{y:.0f}</b> ARS/USD<br>'+
        'Dólar observado: <b>$%{customdata[1]+customdata[2]:.0f}</b> ARS/USD<br>'+
        'Brecha: <b>%{customdata[2]:+.0f}</b> ARS · %{customdata[3]:+.1f}%<br>'+
        '%{customdata[4]}<extra></extra>'
    }
  ],{
    ...common,
    margin:{l:mobile?55:72,r:mobile?12:28,t:mobile?150:132,b:65},
    xaxis:{...common.xaxis,type:'date',tickformat:'%Y',fixedrange:true},
    yaxis:{...common.yaxis,title:'ARS por USD',fixedrange:true},
    shapes:mandateShapesDate(),
    annotations:mandateAnnotationsDate(mobile),
    hovermode:mobile?'closest':'x unified'
  }, {responsive:true,displaylogo:false,displayModeBar:false})
    .then(()=>applyStoredChartScale('bigMacFxChart'));
 }catch(e){el.innerHTML='<div class="note warn">No se pudo cargar el dataset de The Economist.</div>';}
}
async function fetchSeries(id,start='2002-01-01',end=DASHBOARD_SNAPSHOT_CUTOFF){
 const u=`https://apis.datos.gob.ar/series/api/series/?ids=${encodeURIComponent(id)}&start_date=${start}&end_date=${end}&limit=5000&format=json`;
 const j=await(await fetch(u)).json(); const data=j.data||[]; return data.map(r=>[r[0],r[1]]).filter(r=>r[1]!==null&&r[1]!==undefined);
}
let wholesaleRendered=false;
let wholesaleState={traces:[], firstUseful:null, defaultStart:'2016-01-01', mobile:false, fullTimeline:false, windowMonths:60, startIndex:0};

function cleanWholesaleSeries(rows){
  // La API histórica a veces devuelve tramos rellenos con 0.
  // Un 0 aislado puede ser un dato válido; una larga racha inicial de ceros no debe dibujarse como serie.
  const vals=rows.map(r=>[r[0],+r[1]]).filter(r=>Number.isFinite(r[1]));
  const firstMeaningful=vals.findIndex((r,i)=>{
    if(Math.abs(r[1])>0.001) return true;
    // También conservamos un cero si está rodeado de datos no-cero: puede ser una variación mensual real.
    const prev=i>0?vals[i-1][1]:0, next=i<vals.length-1?vals[i+1][1]:0;
    return Math.abs(prev)>0.001 || Math.abs(next)>0.001;
  });
  return firstMeaningful<0 ? [] : vals.slice(firstMeaningful);
}

function monthEndIso(dateStr){
  const [y,m] = dateStr.split('-').map(Number);
  const lastDay = new Date(Date.UTC(y, m, 0)).getUTCDate();
  return `${String(y).padStart(4,'0')}-${String(m).padStart(2,'0')}-${String(lastDay).padStart(2,'0')}`;
}

function wholesaleWhy(name){
  const notes={
    'Eduardo Duhalde':'La salida de la Convertibilidad tuvo una gran corrección cambiaria e inflación de costos, pero esta tarjeta sólo se completa si la serie histórica comparable está efectivamente disponible.',
    'Néstor Kirchner':'La poscrisis combinó recuperación de actividad, recomposición de precios relativos y un tipo de cambio competitivo. Si no hay observaciones compatibles cargadas, no inferimos una trayectoria numérica.',
    'Cristina Fernández':'En este período importan inflación interna, controles de precios y cambiarios, devaluaciones discretas y cambios metodológicos en estadísticas. Si falta una serie homogénea, lo marcamos en vez de fabricar continuidad.',
    'Mauricio Macri':'Los saltos cambiarios —especialmente 2018–2019— suelen transmitirse rápido a precios mayoristas por importados e insumos. Por eso los picos y la dispersión son tan informativos como el promedio.',
    'Alberto Fernández':'La aceleración inflacionaria, controles cambiarios, brechas y shocks de costos dejaron una dinámica mayorista persistentemente alta y volátil; 2023 concentra varios de los máximos del tramo moderno.',
    'Javier Milei':'Diciembre de 2023 y los primeros meses de 2024 muestran el shock inicial de precios relativos y devaluación. Después la variación mayorista desacelera fuerte, aunque con meses y rubros puntuales todavía muy dispares.'
  };
  return notes[name]||'';
}

function buildWholesaleMandateCards(ipim){
  const names=['Eduardo Duhalde','Néstor Kirchner','Cristina Fernández','Mauricio Macri','Alberto Fernández','Javier Milei'];
  const box=document.getElementById('wholesaleMandateCards');
  if(!box) return;

  const fmt=v=>(v>=0?'+':'')+v.toFixed(1).replace('.',',')+'%';
  const cards=names.map(name=>{
    const pts=ipim.filter(r=>presidentForDate(r[0])===name);
    if(!pts.length){
      return `<div class="social-mandate-card">
        <h4>${name}</h4>
        <div class="take"><b>Sin tramo comparable cargado</b><br>No interpreto un 0% ficticio.</div>
        <div class="note" style="margin-top:10px;font-size:.82rem">${wholesaleWhy(name)}</div>
      </div>`;
    }
    const ys=pts.map(r=>+r[1]).filter(Number.isFinite);
    const sorted=[...ys].sort((a,b)=>a-b);
    const median=sorted.length%2?sorted[(sorted.length-1)/2]:(sorted[sorted.length/2-1]+sorted[sorted.length/2])/2;
    const avg=ys.reduce((a,b)=>a+b,0)/ys.length;
    const max=Math.max(...ys), min=Math.min(...ys);
    const meanAbs=ys.reduce((a,b)=>a+Math.abs(b),0)/ys.length;
    const maxPoint=pts[ys.indexOf(max)];
    const minPoint=pts[ys.indexOf(min)];
    const start=pts[0], end=pts[pts.length-1];

    let reading='variación moderada';
    let cls='';
    if(median>=5 || meanAbs>=6){reading='presión mayorista alta'; cls='bad';}
    else if(median<=2.5 && meanAbs<=3.5){reading='presión mayorista relativamente baja'; cls='good';}
    else if(meanAbs>=4.5){reading='dinámica volátil';}

    const fdate=d=>new Date(d+'T00:00:00Z').toLocaleDateString('es-AR',{month:'short',year:'numeric',timeZone:'UTC'});
    return `<div class="social-mandate-card">
      <h4>${name}</h4>
      <div class="line"><span>Mediana mensual</span><b>${fmt(median)}</b></div>
      <div class="line"><span>Promedio mensual</span><b>${fmt(avg)}</b></div>
      <div class="line"><span>Pico</span><b>${fmt(max)}</b></div>
      <div class="line"><span>Piso</span><b>${fmt(min)}</b></div>
      <div class="take"><b class="${cls}">${reading}</b><br>
        Pico: ${fdate(maxPoint[0])} · piso: ${fdate(minPoint[0])}<br>
        <span style="opacity:.78">${fdate(start[0])} → ${fdate(end[0])} · ${ys.length} meses</span>
      </div>
      <div class="note" style="margin-top:10px;font-size:.82rem"><b>¿Qué puede explicarlo?</b> ${wholesaleWhy(name)}</div>
    </div>`;
  });
  box.innerHTML=cards.join('');
}


function wholesaleTimelineMonths(){
  const months=[];
  let y=2002,m=1;
  while(y<2027){
    months.push(`${y}-${String(m).padStart(2,'0')}-01`);
    m++;
    if(m===13){m=1;y++;}
  }
  return months;
}

function formatWholesaleYear(dateStr){
  return dateStr ? dateStr.slice(0,4) : '';
}

function applyWholesaleRangeFromSlider(){
  const slider=document.getElementById('wholesaleRange');
  const chart=document.getElementById('wholesaleChart');
  if(!slider || !chart || !wholesaleState.fullTimeline) return;

  const months=wholesaleTimelineMonths();
  const windowMonths=Number.isFinite(+wholesaleState.windowMonths) && +wholesaleState.windowMonths>1
    ? +wholesaleState.windowMonths
    : 60;
  wholesaleState.windowMonths=windowMonths;

  const rawStart=Number.isFinite(+slider.value) ? +slider.value : 0;
  const maxStart=Math.max(0,months.length-windowMonths);
  const startIndex=Math.max(0,Math.min(rawStart,maxStart));
  const endIndex=Math.min(startIndex+windowMonths-1,months.length-1);

  const from=months[startIndex];
  const to=months[endIndex];
  if(!from || !to){
    console.error('Mayoristas: rango histórico inválido', {startIndex,endIndex,windowMonths});
    return;
  }

  wholesaleState.startIndex=startIndex;
  slider.value=String(startIndex);

  Plotly.relayout(chart,{
    'xaxis.range':[from,to],
    'xaxis.autorange':false
  });

  const fromEl=document.getElementById('wholesaleRangeFrom');
  const toEl=document.getElementById('wholesaleRangeTo');
  if(fromEl) fromEl.textContent=formatWholesaleYear(from);
  if(toEl) toEl.textContent=formatWholesaleYear(to);
}

function setWholesaleDesktopScrollMode(enabled){
  const wrap=document.getElementById('wholesaleChartScroll');
  const chart=document.getElementById('wholesaleChart');
  const hint=document.getElementById('wholesaleDesktopScrollHint');
  if(!wrap || !chart) return;

  if(!wrap.dataset.wheelBound){
    wrap.dataset.wheelBound='1';
    wrap.addEventListener('wheel',(ev)=>{
      if(!wrap.classList.contains('is-scrollable')) return;
      if(wholesaleState.mobile) return;

      const canScroll = wrap.scrollWidth > wrap.clientWidth + 2;
      if(!canScroll) return;

      // Shift+wheel keeps the browser's normal horizontal-wheel intent.
      // Plain vertical wheel becomes horizontal while hovering the historical chart.
      const delta = Math.abs(ev.deltaY) >= Math.abs(ev.deltaX) ? ev.deltaY : ev.deltaX;
      if(!delta) return;

      ev.preventDefault();
      wrap.scrollLeft += delta;
    }, {passive:false});
  }

  if(enabled && !wholesaleState.mobile){
    const months=wholesaleTimelineMonths();
    const hostWidth=wrap.clientWidth || 960;
    const factor=Math.max(2.4, Math.min(6, months.length / 60));
    const targetWidth=Math.round(hostWidth * factor);

    wrap.classList.add('is-scrollable');
    chart.style.width=targetWidth+'px';
    chart.style.minWidth=targetWidth+'px';
    if(hint) hint.style.display='block';

    setTimeout(()=>{
      Plotly.Plots.resize(chart);
      if(wholesaleState.fullTimeline && wrap.scrollLeft===0){
        wrap.scrollLeft=0;
      }
    },0);
  }else{
    wrap.classList.remove('is-scrollable');
    wrap.scrollLeft=0;
    chart.style.width='100%';
    chart.style.minWidth='100%';
    if(hint) hint.style.display='none';
    setTimeout(()=>Plotly.Plots.resize(chart),0);
  }
}

function configureWholesaleRange(){
  const slider=document.getElementById('wholesaleRange');
  const control=document.getElementById('wholesaleRangeControl');
  if(!slider || !control) return;

  const months=wholesaleTimelineMonths();
  const windowMonths=Number.isFinite(+wholesaleState.windowMonths) && +wholesaleState.windowMonths>1 ? +wholesaleState.windowMonths : 60;
  wholesaleState.windowMonths=windowMonths;
  const maxStart=Math.max(0,months.length-windowMonths);
  slider.max=String(maxStart);

  if(!slider.dataset.bound){
    slider.dataset.bound='1';
    slider.addEventListener('input',()=>{slider.dataset.userMoved='1';applyWholesaleRangeFromSlider();});
  }

  if(wholesaleState.fullTimeline){
    control.style.display='';
    // Default historical view starts at Duhalde.
    if(!slider.dataset.userMoved){
      slider.value='0';
      wholesaleState.startIndex=0;
    }else{
      slider.value=String(Math.min(wholesaleState.startIndex,maxStart));
    }
  }else{
    control.style.display='none';
  }
}

function wholesaleApplyTimeline(full){
  const chart=document.getElementById('wholesaleChart');
  if(!chart || !wholesaleState.firstUseful) return;

  wholesaleState.fullTimeline=!!full;
  const toggle=document.getElementById('wholesaleFullTimeline');
  if(toggle && toggle.checked !== wholesaleState.fullTimeline){
    toggle.checked=wholesaleState.fullTimeline;
  }

  const note=document.getElementById('wholesaleCoverageNote');

  if(full){
    configureWholesaleRange();

    if(wholesaleState.mobile){
      setWholesaleDesktopScrollMode(false);
      applyWholesaleRangeFromSlider();
      if(note){
        note.innerHTML=`Vista histórica con zoom: <b>5 años por vez</b>. Deslizá la barra para recorrer desde Duhalde hasta Milei. <b>Cada punto mensual se ubica al cierre del mes</b>, así que dic-2023 ya cuenta dentro de la franja de Milei. La <b>línea rosa</b> marca la <b>devaluación oficial del 13/12/2023</b>. Así las variaciones de 0–3% dejan de quedar aplastadas por los picos de 2023.`;
      }
    }else{
      const months=wholesaleTimelineMonths();
      setWholesaleDesktopScrollMode(true);
      Plotly.relayout(chart,{
        'xaxis.range':[months[0], months[months.length-1]],
        'xaxis.autorange':false,
        shapes:wholesaleShockShapesDate(),
        annotations:wholesaleShockAnnotationsDate(wholesaleState.mobile, wholesaleState.ipimRows || [])
      }).then(()=>setWholesaleDesktopScrollMode(true));
      if(note){
        note.innerHTML=`Vista histórica completa en <b>desktop</b>: el gráfico se expande; con el mouse encima, la <b>ruedita desplaza el tiempo horizontalmente</b>. <b>Cada punto mensual se ubica al cierre del mes</b>, así que dic-2023 queda del lado de Milei. La <b>línea rosa</b> marca la <b>devaluación oficial del 13/12/2023</b>. En mobile seguimos usando la ventana con zoom de 5 años por vez.`;
      }
    }
  }else{
    configureWholesaleRange();
    setWholesaleDesktopScrollMode(false);
    Plotly.relayout(chart,{
      'xaxis.range':[wholesaleState.defaultStart,'2026-08-01'],
      'xaxis.autorange':false,
      shapes:wholesaleShockShapesDate(),
      annotations:wholesaleShockAnnotationsDate(wholesaleState.mobile, wholesaleState.ipimRows || [])
    }).then(()=>setWholesaleDesktopScrollMode(false));
    if(note){
      note.innerHTML=`Vista comparable por defecto: <b>2016 → 2026</b>, donde la lectura conjunta de IPIM, IPIB e IPP es más clara. <b>Cada punto mensual se ubica al cierre del mes</b>, por eso dic-2023 queda después del 10/12 y dentro de la franja de Milei. La <b>línea rosa</b> marca la <b>devaluación oficial del 13/12/2023</b> y el rótulo señala el shock inicial. Activá el checkbox para recorrer el IPIM histórico desde Duhalde con zoom.`;
    }
  }
}

async function renderWholesale(){
 if(wholesaleRendered)return;
 wholesaleRendered=true;
 const el=document.getElementById('wholesaleChart');
 el.innerHTML='<div class="note">Cargando SIPM histórico… ♡</div>';
 try{
   const oldIds={IPIM:'106.3_I1NGVM_1993_M_41',IPIB:'107.3_I1NGVM_1993_M_41',IPP:'108.3_I1NGVM_1993_M_41'};
   const modernIds={IPIM:'448.1_NIVEL_GENERAL_0_0_13_46',IPIB:'449.1_NIVEL_GENERAL_0_0_13_97',IPP:'450.1_NIVEL_GENERAL_0_0_13_97'};
   const traces=[];
   const allcsv=[];
   const cleanedByIndex={};
   const cols={IPIM:'#6c72e8',IPIB:'#48a99c',IPP:'#75a8d9'};

   for(const k of ['IPIM','IPIB','IPP']){
     let old=[];
     try{
       old=cleanWholesaleSeries(await fetchSeries(oldIds[k],'2002-01-01'))
         .map(r=>[monthEndIso(r[0]), +r[1]*100]);
     }catch(e){}
     let lev=[];
     try{lev=await fetchSeries(modernIds[k],'2015-12-01');}catch(e){}
     let modern=[];
     for(let i=1;i<lev.length;i++){
       const prev=+lev[i-1][1],cur=+lev[i][1];
       if(prev && cur) modern.push([monthEndIso(lev[i][0]),(cur/prev-1)*100]);
     }
     modern=cleanWholesaleSeries(modern);

     // No insertamos ceros para cubrir huecos.
     let combo=[...old.filter(r=>r[0]<'2016-01-01'),...modern.filter(r=>r[0]>='2016-01-01')];
     combo=cleanWholesaleSeries(combo);

     if(k==='IPIM'||combo.length){
       combo.push(['2026-07-31',k==='IPP'?0.9:0.8]);
       combo.sort((a,b)=>a[0].localeCompare(b[0]));
     }
     // Sanity check: 2014 IPIM official history contains monthly rates around 1–5%.
     // If historical values are still ~0.01–0.05, unit scaling failed.
     if(k==='IPIM'){
       const check2014=combo.filter(r=>r[0]>='2014-01-01'&&r[0]<'2015-01-01').map(r=>Math.abs(+r[1]));
       if(check2014.length && Math.max(...check2014)<1){
         console.error('SIPM historical unit sanity check failed: values look fractional, not percent.');
       }
     }
     cleanedByIndex[k]=combo;

     if(combo.length){
       traces.push({
         x:combo.map(r=>r[0]),
         y:combo.map(r=>r[1]),
         name:k,
         mode:'lines',
         connectgaps:false,
         line:{color:cols[k],width:k==='IPIM'?2.7:2},
         hovertemplate:`<b>Cierre %{x|%b %Y}</b><br>${k}: <b>%{y:.1f}% mensual</b><extra></extra>`
       });
       combo.forEach(r=>allcsv.push([r[0],k,r[1]]));
     }
   }

   dynamicCsv.wholesale={
     filename:'precios_mayoristas_variacion_mensual_desde_2002.csv',
     content:'fecha,indice,variacion_mensual_pct\\n'+
       allcsv.sort((a,b)=>a[0].localeCompare(b[0])).map(r=>r.join(',')).join('\\n')
   };

   const allDates=Object.values(cleanedByIndex).flat().map(r=>r[0]).sort();
   const firstUseful=allDates[0]||'2016-01-01';
   const mobile=window.innerWidth<=720;
   wholesaleState={
     traces,
     ipimRows: cleanedByIndex.IPIM || [],
     firstUseful,
     defaultStart:'2016-01-01',
     mobile,
     fullTimeline:false,
     windowMonths:60,
     startIndex:0
   };

   el.innerHTML='';
   Plotly.newPlot('wholesaleChart',traces,{
     ...common,
     margin:{l:mobile?55:72,r:mobile?12:28,t:mobile?155:130,b:70},
     xaxis:{
       ...common.xaxis,
       type:'date',
       range:['2016-01-01','2026-08-01'],
       dtick:mobile?'M24':'M12',
       tickformat:'%Y',
       fixedrange:true
     },
     yaxis:{
       ...common.yaxis,
       title:'Variación mensual (%)',
       zeroline:true,
       zerolinecolor:'#8d77a0',
       ticksuffix:'%',
       fixedrange:true
     },
     shapes:wholesaleShockShapesDate(),
     annotations:wholesaleShockAnnotationsDate(mobile, cleanedByIndex.IPIM || []),
     hovermode:mobile?'closest':'x unified'
   }, {responsive:true,displaylogo:false,displayModeBar:false});

   buildWholesaleMandateCards(cleanedByIndex.IPIM||[]);

   function buildWholesalePlainConclusion(ipim){
     const box=document.getElementById('wholesalePlainConclusion');
     if(!box || !ipim.length) return;
     const alberto=ipim.filter(r=>presidentForDate(r[0])==='Alberto Fernández');
     const milei=ipim.filter(r=>presidentForDate(r[0])==='Javier Milei');
     if(!alberto.length || !milei.length){
       box.innerHTML='<span class="label">Conclusión</span><strong>No hay suficientes datos comparables para resumir el cambio entre Alberto y Milei.</strong>';
       return;
     }
     const median=arr=>{
       const a=arr.map(r=>+r[1]).filter(Number.isFinite).sort((x,y)=>x-y);
       if(!a.length) return null;
       return a.length%2?a[(a.length-1)/2]:(a[a.length/2-1]+a[a.length/2])/2;
     };
     const avg=arr=>{
       const a=arr.map(r=>+r[1]).filter(Number.isFinite);
       return a.reduce((x,y)=>x+y,0)/a.length;
     };
     const tail=(arr,n)=>arr.slice(Math.max(0,arr.length-n));
     const prev6=tail(alberto,6);
     const first6=milei.slice(0,Math.min(6,milei.length));
     const recent6=tail(milei,6);
     const prevMed=median(prev6), firstMed=median(first6), recentMed=median(recent6);
     const prevAvg=avg(prev6), firstAvg=avg(first6), recentAvg=avg(recent6);
     const peak=Math.max(...milei.map(r=>+r[1]));
     const fmt=x=>(x>=0?'+':'')+x.toFixed(1).replace('.',',')+'%';

     let verdict='La presión mayorista reciente está en niveles parecidos a los últimos meses de Alberto.';
     if(recentMed <= prevMed-1.5) verdict='La presión mayorista reciente es <b>claramente menor</b> que la que dejó Alberto.';
     else if(recentMed >= prevMed+1.5) verdict='La presión mayorista reciente es <b>mayor</b> que la que dejó Alberto.';

     const shock = firstMed > prevMed+3
       ? 'El arranque de Milei fue mucho más brusco que el cierre de Alberto: hubo un shock inicial de precios mayoristas.'
       : 'El arranque de Milei no fue sustancialmente más alto que el cierre de Alberto en esta métrica.';

     box.innerHTML=`
       <span class="label">Si sólo te llevás una cosa de este tab 🏭</span>
       <strong>${verdict}</strong>
       Tomando los últimos 6 meses de Alberto, la mediana mensual del IPIM fue <b>${fmt(prevMed)}</b>. En los primeros meses de Milei fue <b>${fmt(firstMed)}</b> y en los últimos 6 meses disponibles bajó a <b>${fmt(recentMed)}</b>.
       <br><br><b>La historia corta:</b> ${shock} Después, los aumentos mayoristas se desaceleraron con fuerza. El máximo registrado dentro de la gestión fue <b>${fmt(peak)}</b>, mientras que el promedio de los últimos 6 meses es <b>${fmt(recentAvg)}</b>.
       <br><br><b>¿Eso es una buena noticia?</b> Sí, <b>en este indicador puntual</b>: menos inflación mayorista significa menos presión nueva sobre costos de bienes e insumos. Pero no borra lo que pasó antes: los precios que ya subieron no vuelven atrás, y un IPIM bajo no garantiza por sí solo salarios recuperados, consumo fuerte ni IPC igualmente bajo.
       <br><br><b>Comparado con lo heredado:</b> Alberto dejó una economía con presión mayorista elevada y creciente; Milei tuvo primero un salto todavía mayor y después consiguió una desaceleración muy marcada. La conclusión más justa es <b>“shock inicial fuerte + estabilización posterior”</b>, no simplemente “todo mejor” ni “todo peor”.
     `;
   }
   buildWholesalePlainConclusion(cleanedByIndex.IPIM||[]);
   wholesaleApplyTimeline(false);

   const toggle=document.getElementById('wholesaleFullTimeline');
   if(toggle){
     toggle.checked=false;
     if(!toggle.dataset.bound){
       toggle.dataset.bound='1';
       toggle.addEventListener('change',()=>wholesaleApplyTimeline(toggle.checked));
     }
   }

   Plotly.newPlot('wholesaleCurrentChart',[{
     type:'bar',
     x:['IPIM · primarios','IPIM · manufacturados','IPIM · electricidad','IPIM · importados','IPIB · primarios','IPIB · manufacturados','IPIB · electricidad','IPP · primarios','IPP · manufacturados','IPP · electricidad'],
     y:[-2.2,1.7,5.8,.5,-1.1,1.5,5.8,-1.0,1.5,5.8],
     marker:{color:['#6c72e8','#6c72e8','#6c72e8','#6c72e8','#48a99c','#48a99c','#48a99c','#75a8d9','#75a8d9','#75a8d9']},
     hovertemplate:'<b>%{x}</b><br>%{y:.1f}%<extra></extra>'
   }],{
     ...common,
     margin:{l:55,r:20,t:40,b:mobile?145:120},
     xaxis:{tickangle:-35,fixedrange:true},
     yaxis:{title:'Variación mensual jul-2026 (%)',zeroline:true,zerolinecolor:'#8d77a0',fixedrange:true},
     showlegend:false
   },{responsive:true,displaylogo:false,displayModeBar:false});

 }catch(e){
   el.innerHTML='<div class="note warn">No se pudo consultar la API de series históricas en este momento.</div>';
 }
}

