function downloadEmbeddedCsv(key) {
  const item = embeddedCsvDownloads[key];
  if (!item) return;
  const bom = '\uFEFF';
  const blob = new Blob([bom + item.content], {type:'text/csv;charset=utf-8'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = item.filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}


function renderPovertyMandateChart() {
  const mobile = window.innerWidth <= 720;

  const y = povertyMandateChanges.map(d => d.presidente);
  const x = povertyMandateChanges.map(d => d.cambio);
  const custom = povertyMandateChanges.map(d => [
    d.inicio,
    d.final,
    d.relativo,
    d.cambio < 0 ? 'Bajó' : 'Subió',
    d.base,
    d.cierre
  ]);

  Plotly.react('povertyMandateChart', [{
    type:'bar',
    orientation:'h',
    y:y,
    x:x,
    customdata:custom,
    marker:{
      color:x.map(v => v < 0 ? '#68c7a1' : '#ef809e')
    },
    text:x.map(v => (v < 0 ? '↓ ' : '↑ ') + Math.abs(v).toFixed(1).replace('.', ',') + ' pp'),
    textposition:'outside',
    cliponaxis:false,
    hovertemplate:
      '<b>%{y}</b><br>' +
      '%{customdata[3]}: <b>%{x:.1f} pp</b><br>' +
      'Base %{customdata[4]}: %{customdata[0]:.1f}%<br>' +
      'Cierre %{customdata[5]}: %{customdata[1]:.1f}%<br>' +
      'Cambio relativo: %{customdata[2]:.1f}%<extra></extra>'
  }], {
    paper_bgcolor:'rgba(255,255,255,0)',
    plot_bgcolor:'#fffdfd',
    font:{color:'#5e4670',family:'Inter,system-ui,sans-serif'},
    margin:{
      l: mobile ? 118 : 150,
      r: mobile ? 55 : 85,
      t: 24,
      b: 58
    },
    xaxis:{
      title:'Cambio de pobreza (puntos porcentuales)',
      range:[-25,10],
      zeroline:true,
      zerolinecolor:'#b899c7',
      zerolinewidth:2,
      gridcolor:'#efe4f4',
      linecolor:'#d9c2e5',
      tickfont:{color:'#7b6688',size:mobile?10:12},
      fixedrange:true
    },
    yaxis:{
      autorange:'reversed',
      gridcolor:'rgba(0,0,0,0)',
      tickfont:{color:'#654c73',size:mobile?11:13},
      fixedrange:true
    },
    showlegend:false,
    hoverlabel:{
      bgcolor:'#fff7fb',
      bordercolor:'#efb7d0',
      font:{color:'#4d365c',size:14}
    },
    shapes:[{
      type:'line',
      x0:0,x1:0,
      yref:'paper',y0:0,y1:1,
      line:{color:'#a987b9',width:1.7,dash:'dash'}
    }],
    annotations:[
      {
        xref:'paper',x:.18,y:.98,yref:'paper',xanchor:'center',yanchor:'top',
        text:'← bajó la pobreza',
        showarrow:false,
        font:{color:'#2d8061',size:mobile?9:11},
        bgcolor:'rgba(255,255,255,.86)',borderpad:2
      },
      {
        xref:'paper',x:.82,y:.98,yref:'paper',xanchor:'center',yanchor:'top',
        text:'subió la pobreza →',
        showarrow:false,
        font:{color:'#b54d6b',size:mobile?9:11},
        bgcolor:'rgba(255,255,255,.86)',borderpad:2
      }
    ]
  }, {
    responsive:true,
    displaylogo:false,
    displayModeBar:false,
    scrollZoom:false,
    doubleClick:false
  });

  setTimeout(bindPlotlyClickTracking, 50);
}

